window.QUIZ={"key": "anat", "title": "Anatomie-Quiz", "decks": [{"id": "anat", "name": "Anatomie Thorax/Abdomen (Altfragen)", "q": [{"id": "anat-herz-01", "ch": "1 Herz und große Gefäße", "q": "Aus welcher Koronararterie entspringt beim Rechtsversorgungstyp der Ramus interventricularis posterior (RIVP)?", "o": ["Arteria coronaria sinistra", "Ramus circumflexus (sinister)", "Arteria coronaria dextra", "Ramus marginalis sinister"], "a": 2, "e": "Beim Rechts- und auch beim Normalversorgungstyp geht der RIVP aus der A. coronaria dextra hervor; nur beim Linksversorgungstyp stammt er aus dem Ramus circumflexus."}, {"id": "anat-herz-02", "ch": "1 Herz und große Gefäße", "q": "Welches Koronargefäß versorgt beim Normalversorgungstyp den rechten Ventrikel?", "o": ["Ramus interventricularis anterior", "Ramus circumflexus sinister", "Arteria coronaria dextra", "Arteria coronaria sinistra"], "a": 2, "e": "Die A. coronaria dextra versorgt rechten Vorhof, rechten Ventrikel, das hintere Septumdrittel (über den RIVP) und meist Sinus- und AV-Knoten."}, {"id": "anat-herz-03", "ch": "1 Herz und große Gefäße", "q": "Der Verschluss welchen Gefäßes verursacht typischerweise einen Vorderwandinfarkt?", "o": ["Ramus circumflexus sinister", "Ramus marginalis dexter", "Ramus interventricularis posterior", "Ramus interventricularis anterior"], "a": 3, "e": "Der RIVA (engl. LAD) aus der A. coronaria sinistra versorgt Vorderwand des linken Ventrikels und die vorderen zwei Drittel des Septums; sein Verschluss führt zum Vorderwandinfarkt."}, {"id": "anat-herz-04", "ch": "1 Herz und große Gefäße", "q": "Welche Gefäße versorgen den vorderen und mittleren Teil (vordere zwei Drittel) des Septum interventriculare?", "o": ["Rami interventriculares septales des RIVP", "Rami interventriculares septales des RIVA", "Rami atriales des Ramus circumflexus", "Ramus marginalis dexter der rechten Arterie"], "a": 1, "e": "Die Septumäste des Ramus interventricularis anterior versorgen die vorderen zwei Drittel, die des RIVP das hintere Drittel des Kammerseptums – inklusive Tawara-Schenkeln."}, {"id": "anat-herz-05", "ch": "1 Herz und große Gefäße", "q": "Welches Gefäß versorgt beim Normalversorgungstyp den Atrioventrikularknoten (AV-Knoten)?", "o": ["Ramus nodi atrioventricularis der rechten Koronararterie", "Ramus marginalis sinister der linken Koronararterie", "Ramus interventricularis anterior der linken Koronararterie", "Ramus nodi atrioventricularis aus dem Ramus circumflexus"], "a": 0, "e": "Der R. nodi atrioventricularis entspringt in ca. 80–90 % aus der A. coronaria dextra im Bereich der Crux cordis (nahe Abgang des RIVP)."}, {"id": "anat-herz-06", "ch": "1 Herz und große Gefäße", "q": "Welche Koronararterie versorgt überwiegend das Erregungsbildungs- und -leitungssystem (EBLS) – Vorsicht beim Linksversorgungstyp?", "o": ["Ramus marginalis sinister", "Arteria coronaria sinistra", "Ramus interventricularis anterior", "Arteria coronaria dextra"], "a": 3, "e": "Sinusknotenarterie (ca. 60 %) und AV-Knotenarterie (ca. 80–90 %) stammen meist aus der A. coronaria dextra; beim Linksversorgungstyp kommt die AV-Knotenarterie aus dem R. circumflexus."}, {"id": "anat-herz-07", "ch": "1 Herz und große Gefäße", "q": "In welcher Herzphase erfolgt die Durchblutung der Koronararterien (v. a. links) überwiegend?", "o": ["In der Systole", "In der Austreibungsphase", "In der Diastole", "In der Anspannungsphase"], "a": 2, "e": "In der Systole komprimiert das kontrahierende Myokard die intramuralen Gefäße; deshalb fließt das Blut v. a. in der Diastole. Die Koronarostien liegen in den Sinus aortae oberhalb der Taschenklappen."}, {"id": "anat-herz-08", "ch": "1 Herz und große Gefäße", "q": "Wo liegt der Sinusknoten?", "o": ["Im Septum interventriculare, Pars membranacea, unter der Aortenklappe", "Subepikardial im Sulcus terminalis an der Mündung der oberen Hohlvene", "Subendokardial im Koch-Dreieck nahe dem Ostium sinus coronarii", "Am Limbus fossae ovalis im Septum interatriale des linken Vorhofs"], "a": 1, "e": "Der Sinusknoten (Keith-Flack) liegt subepikardial im Sulcus terminalis (innen: Crista terminalis) an der Einmündung der V. cava superior und ist der primäre Schrittmacher."}, {"id": "anat-herz-09", "ch": "1 Herz und große Gefäße", "q": "Welche Strukturen begrenzen das Koch-Dreieck im rechten Vorhof?", "o": ["Trabecula septomarginalis, Crista supraventricularis, Conus arteriosus", "Todaro-Sehne, Ansatz des septalen Trikuspidalsegels, Ostium sinus coronarii", "Valvula venae cavae inferioris, Fossa ovalis, Auricula dextra", "Crista terminalis, Limbus fossae ovalis, Ostium venae cavae superioris"], "a": 1, "e": "Im Koch-Dreieck liegt der AV-Knoten. Die Todaro-Sehne zieht von der Valvula venae cavae inferioris zum Trigonum fibrosum dextrum (Zentralkörper)."}, {"id": "anat-herz-10", "ch": "1 Herz und große Gefäße", "q": "Welche Struktur liegt im Koch-Dreieck, und welche Rolle hat sie im Erregungssystem?", "o": ["His-Bündel – primärer Schrittmacher", "AV-Knoten – nur sekundärer Schrittmacher", "AV-Knoten – primärer Schrittmacher", "Sinusknoten – primärer Schrittmacher"], "a": 1, "e": "Der AV-Knoten verzögert die Überleitung auf die Kammern; als Schrittmacher springt er nur bei Sinusknotenausfall ein (Eigenfrequenz ca. 40–60/min)."}, {"id": "anat-herz-11", "ch": "1 Herz und große Gefäße", "q": "Wo liegt die Fossa ovalis, und was ist sie entwicklungsgeschichtlich?", "o": ["Im Septum interatriale; Rest des Ductus venosus", "Im Septum interatriale (rechts); Rest des Foramen ovale", "Im Septum interventriculare; Rest des Ductus arteriosus", "In der Wand des rechten Ventrikels; Rest des Sinus venosus"], "a": 1, "e": "Fetal fließt Blut durch das Foramen ovale vom rechten in den linken Vorhof (Umgehung der Lunge); postnatal verschließt es sich zur Fossa ovalis mit Limbus fossae ovalis."}, {"id": "anat-herz-12", "ch": "1 Herz und große Gefäße", "q": "Warum ist ein persistierendes Foramen ovale (PFO) klinisch relevant?", "o": ["Es führt regelhaft zu einer Zyanose schon im Neugeborenenalter", "Es erzeugt einen Links-rechts-Shunt zwischen beiden Ventrikeln", "Paradoxe Embolie: venöse Thromben gelangen in den Körperkreislauf", "Es verursacht eine Aortenisthmusstenose mit Hypertonie der Arme"], "a": 2, "e": "Bei Druckanstieg im rechten Vorhof (z. B. Pressen) kann ein venöser Embolus über das PFO in den linken Vorhof und so z. B. ins Gehirn gelangen (Schlaganfall)."}, {"id": "anat-herz-13", "ch": "1 Herz und große Gefäße", "q": "Was ist das Ligamentum (Lig.) arteriosum?", "o": ["Rest der Arteria umbilicalis an der vorderen Bauchwand", "Rest des Ductus venosus zwischen Vena umbilicalis und unterer Hohlvene", "Bindegewebsband, das die Aorta ascendens am Perikard fixiert", "Rest des Ductus arteriosus zwischen Truncus pulmonalis und Aortenbogen"], "a": 3, "e": "Der Ductus arteriosus (Botalli) leitet fetal Blut vom Truncus pulmonalis in die Aorta. Um das Lig. arteriosum schlingt sich der N. laryngeus recurrens sinister."}, {"id": "anat-herz-14", "ch": "1 Herz und große Gefäße", "q": "Welche fetale Funktion hatte die Valvula venae cavae inferioris (Eustachi-Klappe)?", "o": ["Sie verschloss das Ostium sinus coronarii in der Systole", "Sie leitete Blut aus dem Truncus pulmonalis in die Aorta", "Sie verhinderte den Rückstrom aus dem rechten Ventrikel", "Sie lenkte das Blut der unteren Hohlvene zum Foramen ovale"], "a": 3, "e": "Das sauerstoffreiche Plazentablut der V. cava inferior wurde durch die Eustachi-Klappe zum Foramen ovale und damit in den linken Vorhof gelenkt."}, {"id": "anat-herz-15", "ch": "1 Herz und große Gefäße", "q": "Welcher Herzrand wird als Margo obtusus bezeichnet, und welche Herzhöhle bildet ihn?", "o": ["Oberer Herzrand, gebildet vom linken Vorhof", "Rechter Herzrand, gebildet vom rechten Vorhof", "Unterer Herzrand, gebildet vom rechten Ventrikel", "Linker Herzrand, gebildet vom linken Ventrikel"], "a": 3, "e": "Margo obtusus = linker, stumpfer Rand (linker Ventrikel); Margo dexter (acutus) = scharfer unterer rechter Rand (rechter Ventrikel)."}, {"id": "anat-herz-16", "ch": "1 Herz und große Gefäße", "q": "Welche Herzklappe liegt nicht in der Ventilebene?", "o": ["Pulmonalklappe", "Trikuspidalklappe", "Aortenklappe", "Mitralklappe"], "a": 0, "e": "Die Pulmonalklappe liegt am Ende des Conus arteriosus etwas oberhalb und ventral der Ventilebene; Aorten-, Mitral- und Trikuspidalklappe sind am Herzskelett in der Ventilebene verankert."}, {"id": "anat-herz-17", "ch": "1 Herz und große Gefäße", "q": "Was enthält die Trabecula septomarginalis, und wohin zieht sie?", "o": ["Rechten Tawara-Schenkel; zum vorderen Papillarmuskel rechts", "Das His-Bündel; vom Conus arteriosus zur Pulmonalklappe", "Linken Tawara-Schenkel; zum hinteren Papillarmuskel links", "Den AV-Knoten; vom Septum zur Crista terminalis rechts"], "a": 0, "e": "Die Trabecula septomarginalis (Moderatorband) im rechten Ventrikel führt den rechten Tawara-Schenkel vom Septum zum M. papillaris anterior."}, {"id": "anat-herz-18", "ch": "1 Herz und große Gefäße", "q": "Welche Struktur trennt im rechten Ventrikel die Einstrom- von der Ausstrombahn?", "o": ["Sulcus interventricularis", "Crista terminalis", "Crista supraventricularis", "Limbus fossae ovalis"], "a": 2, "e": "Die Crista supraventricularis (mit der Trabecula septomarginalis) trennt die Einstrombahn (Trikuspidalklappe) von der Ausstrombahn (Conus arteriosus → Pulmonalklappe)."}, {"id": "anat-herz-19", "ch": "1 Herz und große Gefäße", "q": "Was ist der Conus arteriosus?", "o": ["Trabekelreicher Einflussbereich des linken Ventrikels an der Mitralklappe", "Glattwandige Ausflussbahn des rechten Ventrikels zum Truncus pulmonalis", "Glattwandiger Abschnitt des linken Vorhofs an den Lungenvenen", "Muskelwulst im rechten Vorhof zwischen beiden Hohlvenenmündungen"], "a": 1, "e": "Der Conus arteriosus (Infundibulum) ist trabekelfrei und endet an der Valva trunci pulmonalis."}, {"id": "anat-herz-20", "ch": "1 Herz und große Gefäße", "q": "Über welchen Abschnitt verlässt das Blut den linken Ventrikel?", "o": ["Vestibulum aortae, dann Valva aortae", "Conus arteriosus, dann Valva trunci pulmonalis", "Sinus venarum cavarum, dann Valva aortae", "Auricula sinistra, dann Valva mitralis"], "a": 0, "e": "Die Ausstrombahn links ist das glattwandige Vestibulum aortae unter der Aortenklappe; vorderes Mitralsegel trennt Ein- und Ausstrombahn."}, {"id": "anat-herz-21", "ch": "1 Herz und große Gefäße", "q": "Welche Funktion haben die Papillarmuskeln?", "o": ["Sie verschließen die Taschenklappen am Ende der Systole", "Sie öffnen die Segelklappen aktiv zu Beginn der Diastole", "Sie leiten die Erregung vom Sinusknoten zum AV-Knoten", "Sie verhindern über Chordae das Durchschlagen der Segel in der Systole"], "a": 3, "e": "Die Papillarmuskeln kontrahieren mit dem Ventrikel und halten die Segel über die Chordae tendineae, sodass diese nicht in den Vorhof prolabieren; das Öffnen der Klappen erfolgt passiv durch Druck."}, {"id": "anat-herz-22", "ch": "1 Herz und große Gefäße", "q": "Welche Herzklappe besitzt eine Cuspis septalis?", "o": ["Trikuspidalklappe", "Aortenklappe", "Mitralklappe", "Pulmonalklappe"], "a": 0, "e": "Trikuspidalklappe: Cuspis anterior, posterior, septalis. Mitralklappe: Cuspis anterior und posterior. Taschenklappen haben Valvulae semilunares."}, {"id": "anat-herz-23", "ch": "1 Herz und große Gefäße", "q": "Was ist der Nodulus einer Taschenklappe?", "o": ["Knötchen in der Mitte des freien Klappenrandes", "Ansatzpunkt der Chordae tendineae am Segelrand", "Muskelwulst an der Basis eines Papillarmuskels", "Mündungsstelle der Koronararterie im Sinus"], "a": 0, "e": "Die Noduli valvularum semilunarium liegen mittig am freien Rand, seitlich davon die dünnen Lunulae; sie dichten den Klappenschluss im Zentrum ab."}, {"id": "anat-herz-24", "ch": "1 Herz und große Gefäße", "q": "Wo mündet der Sinus coronarius?", "o": ["In den linken Vorhof neben den Lungenvenenmündungen", "Direkt in den rechten Ventrikel unter der Trikuspidalklappe", "In den rechten Vorhof nahe der unteren Hohlvenenmündung", "In die obere Hohlvene oberhalb des Sinusknotens"], "a": 2, "e": "Der Sinus coronarius verläuft im hinteren Sulcus coronarius und mündet zwischen Ostium venae cavae inferioris und Trikuspidalklappe (mit Valvula sinus coronarii)."}, {"id": "anat-herz-25", "ch": "1 Herz und große Gefäße", "q": "In welchem Sulcus verläuft die Vena (V.) cardiaca media?", "o": ["Sulcus interventricularis posterior", "Sulcus coronarius, linker Abschnitt", "Sulcus terminalis cordis", "Sulcus interventricularis anterior"], "a": 0, "e": "Die V. cardiaca media (V. interventricularis posterior) begleitet den RIVP und mündet in den Sinus coronarius; die V. cardiaca magna begleitet den RIVA."}, {"id": "anat-herz-26", "ch": "1 Herz und große Gefäße", "q": "Welches Gefäß transportiert im Venenkreuz an der Herzhinterseite sauerstoffreiches Blut?", "o": ["Eine Vena pulmonalis", "Die Vena cava superior", "Die Vena cava inferior", "Der Sinus coronarius"], "a": 0, "e": "Im Venenkreuz kreuzen die horizontal verlaufenden Vv. pulmonales (O2-reich, zum linken Vorhof) die vertikale Achse aus V. cava superior und inferior."}, {"id": "anat-herz-27", "ch": "1 Herz und große Gefäße", "q": "Wo verläuft der Ramus circumflexus?", "o": ["Im linken Sulcus coronarius nach dorsal", "Im rechten Sulcus coronarius nach dorsal", "Im Sulcus interventricularis anterior", "Im Sulcus interventricularis posterior"], "a": 0, "e": "Der R. circumflexus der A. coronaria sinistra umrundet links im Sulcus coronarius das Herz und versorgt linken Vorhof sowie Seiten- und Hinterwand des linken Ventrikels."}, {"id": "anat-herz-28", "ch": "1 Herz und große Gefäße", "q": "Wodurch wird das Septum interventriculare von außen markiert?", "o": ["Crista terminalis und Crista supraventricularis", "Margo dexter und Margo obtusus", "Sulcus coronarius und Sulcus terminalis", "Sulci interventriculares anterior und posterior"], "a": 3, "e": "In den Sulci interventriculares verlaufen RIVA/V. cardiaca magna (vorn) und RIVP/V. cardiaca media (hinten)."}, {"id": "anat-herz-29", "ch": "1 Herz und große Gefäße", "q": "Aus welchen Anteilen besteht das Septum interventriculare?", "o": ["Pars muscularis und Pars membranacea", "Pars muscularis und Pars tendinea", "Pars sinuatrialis und Pars fibrosa", "Septum primum und Septum secundum"], "a": 0, "e": "Die kleine Pars membranacea liegt unter der Aortenklappe und ist häufigster Ort von Ventrikelseptumdefekten; Septum primum/secundum betreffen das Vorhofseptum."}, {"id": "anat-herz-30", "ch": "1 Herz und große Gefäße", "q": "Warum sind Vorhof- und Kammermyokard elektrisch voneinander isoliert?", "o": ["Damit die Koronararterien in der Systole nicht komprimiert werden", "Damit die Vorhöfe und Kammern sich exakt gleichzeitig zusammenziehen", "Damit der Sinusknoten direkt auf das Kammermyokard überleiten kann", "Damit die Erregung nur über den AV-Knoten verzögert auf die Kammern übergeht"], "a": 3, "e": "Das Herzskelett (Anuli fibrosi) trennt Vorhof und Kammer elektrisch; nur über AV-Knoten/His-Bündel wird erregt. So kontrahieren erst die Vorhöfe (Kammerfüllung), dann die Kammern."}, {"id": "anat-herz-31", "ch": "1 Herz und große Gefäße", "q": "Was sind die ersten Abgänge der Aorta?", "o": ["Die Arteriae intercostales posteriores", "Die Arteria subclavia sinistra aus dem Arcus", "Die Koronararterien aus den Sinus aortae", "Der Truncus brachiocephalicus aus dem Arcus"], "a": 2, "e": "Die Aa. coronariae entspringen aus der Aorta ascendens (Sinus aortae dexter/sinister) direkt oberhalb der Aortenklappe; erster Ast des Aortenbogens ist der Truncus brachiocephalicus."}, {"id": "anat-herz-32", "ch": "1 Herz und große Gefäße", "q": "Welcher Ast geht als erster vom Arcus aortae ab?", "o": ["Arteria carotis communis sinistra", "Arteria subclavia sinistra", "Arteria thoracica interna", "Truncus brachiocephalicus"], "a": 3, "e": "Reihenfolge am Aortenbogen: Truncus brachiocephalicus (→ A. subclavia dextra + A. carotis communis dextra), A. carotis communis sinistra, A. subclavia sinistra."}, {"id": "anat-herz-33", "ch": "1 Herz und große Gefäße", "q": "Was markiert der Sulcus terminalis cordis außen am rechten Vorhof?", "o": ["Grenze zwischen Sinus venarum cavarum und Atrium proprium", "Grenze zwischen linkem und rechtem Herzohr", "Verlauf des Ramus interventricularis posterior", "Grenze zwischen rechtem Vorhof und rechtem Ventrikel"], "a": 0, "e": "Innen entspricht ihm die Crista terminalis; im oberen Abschnitt liegt subepikardial der Sinusknoten."}, {"id": "anat-lunge-01", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Welcher Bronchus liegt hyparteriell, also unterhalb der zugehörigen Pulmonalarterie?", "o": ["Bronchus lobaris medius dexter", "Bronchus principalis sinister", "Bronchus principalis dexter", "Bronchus lobaris superior dexter"], "a": 1, "e": "Links überquert die A. pulmonalis sinistra den Hauptbronchus (hyparteriell); rechts liegt der Oberlappenbronchus oberhalb der A. pulmonalis dextra (eparteriell)."}, {"id": "anat-lunge-02", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Welcher Bronchus wird als eparteriell bezeichnet?", "o": ["Bronchus lobaris superior sinister", "Bronchus principalis sinister", "Bronchus lobaris inferior dexter", "Bronchus lobaris superior dexter"], "a": 3, "e": "Der rechte Oberlappenbronchus geht oberhalb der Kreuzung mit der A. pulmonalis dextra ab; die Arterie liegt rechts also kaudal von ihm."}, {"id": "anat-lunge-03", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "In welchen Hauptbronchus gelangen aspirierte Fremdkörper am häufigsten, und warum?", "o": ["In den rechten, weil er länger und enger ist", "In den linken, weil er weiter und kürzer ist", "In den rechten, weil er steiler und weiter ist", "In den linken, weil er steiler und kürzer ist"], "a": 2, "e": "Der rechte Hauptbronchus ist kürzer, weiter und steiler (ca. 20–25° zur Vertikalen) als der linke (ca. 45°), der vom Aortenbogen abgedrängt wird."}, {"id": "anat-lunge-04", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Was entspricht in der linken Lunge dem Lobus medius der rechten Lunge?", "o": ["Apex pulmonis sinistri", "Lingula pulmonis sinistri", "Incisura cardiaca", "Lobus inferior sinister"], "a": 1, "e": "Die Lingula (Segmente 4 und 5) ist Teil des linken Oberlappens und entspricht dem rechten Mittellappen."}, {"id": "anat-lunge-05", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Wo befindet sich die Incisura cardiaca pulmonis sinistri?", "o": ["Am Unterrand des linken Unterlappens", "An der Facies mediastinalis rechts", "Am Hinterrand des linken Unterlappens", "Am Vorderrand des linken Oberlappens"], "a": 3, "e": "Die Herzaussparung liegt am Margo anterior des linken Oberlappens oberhalb der Lingula; hier liegt das Herz der Brustwand direkt an."}, {"id": "anat-lunge-06", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Wie viele bronchopulmonale Segmente haben rechte und linke Lunge typischerweise?", "o": ["Rechts 8, links 8 Segmente", "Rechts 10, links 9 Segmente", "Rechts 10, links 10 Segmente", "Rechts 9, links 10 Segmente"], "a": 1, "e": "Links fehlt meist Segment 7 (mediobasal); häufig sind links S1 und S2 zu einem apikoposterioren Segment verschmolzen."}, {"id": "anat-lunge-07", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Welches Gefäß verläuft intrasegmental mit dem Segmentbronchus?", "o": ["Ast der Vena azygos", "Ast der Vena thoracica interna", "Ast der Arteria pulmonalis", "Ast der Vena pulmonalis"], "a": 2, "e": "Segmentarterien begleiten zentral den Segmentbronchus (bronchoarterielle Einheit); die Vv. pulmonales verlaufen intersegmental und markieren die Segmentgrenzen – wichtig für Segmentresektionen."}, {"id": "anat-lunge-08", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Welche Struktur liegt am linken Lungenhilum am weitesten kranial?", "o": ["Arteria pulmonalis sinistra", "Ligamentum pulmonale", "Bronchus principalis sinister", "Vena pulmonalis inferior"], "a": 0, "e": "Links: Arterie oben, Bronchus dahinter/darunter, Venen vorn-unten. Rechts liegt der eparterielle Oberlappenbronchus am höchsten, die Arterie kaudal davon."}, {"id": "anat-lunge-09", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Welche Lymphknoten an der Bifurcatio tracheae sind eine zentrale Station des Lungenlymphabflusses?", "o": ["Nodi lymphoidei tracheobronchiales inferiores", "Nodi lymphoidei intrapulmonales", "Nodi lymphoidei mediastinales posteriores", "Nodi lymphoidei paratracheales superiores"], "a": 0, "e": "Weg: Nll. intrapulmonales → bronchopulmonales (Hilus) → tracheobronchiales inferiores (Bifurkation) und superiores → paratracheales → Truncus bronchomediastinalis."}, {"id": "anat-lunge-10", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Welche Strukturen liegen kranial des Apex pulmonis und sind beim Pancoast-Tumor gefährdet?", "o": ["Plexus brachialis, Arteria und Vena subclavia", "Nervus phrenicus und Vasa thoracica interna", "Arcus aortae und Nervus laryngeus recurrens", "Vena azygos und Ductus thoracicus"], "a": 0, "e": "Die Lungenspitze ragt in die obere Thoraxapertur (Cupula pleurae); ein Pancoast-Tumor kann Plexus brachialis (Schmerzen, Lähmungen) und Ganglion stellatum (Horner-Syndrom) infiltrieren."}, {"id": "anat-lunge-11", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Welche Vene zieht im oberen Mediastinum rechts neben der Trachea über den rechten Hauptbronchus zur oberen Hohlvene?", "o": ["Vena brachiocephalica dextra", "Arcus venae azygos", "Vena thoracica interna", "Vena hemiazygos accessoria"], "a": 1, "e": "Rechts der Trachea liegen Arcus venae azygos, V. cava superior und N. vagus dexter; lateral schließt die Pleura des rechten Oberlappens an."}, {"id": "anat-lunge-12", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Was ist das Ligamentum pulmonale?", "o": ["Faserband zwischen Lungenspitze und erster Rippe", "Pleuraduplikatur unterhalb des Lungenhilums", "Rest des Ductus arteriosus am Lungenhilum", "Bandverbindung zwischen Trachea und Aortenbogen"], "a": 1, "e": "An der Hilumumschlagfalte gehen Pleura visceralis und mediastinalis ineinander über; kaudal läuft diese Falte als Lig. pulmonale aus."}, {"id": "anat-lunge-13", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Wo liegt der Paries membranaceus der Trachea und woran grenzt er?", "o": ["Ventral; grenzt an den Isthmus der Schilddrüse", "Dorsal; grenzt an den Ösophagus", "Ventral; grenzt an den Aortenbogen", "Lateral rechts; grenzt an die Vena azygos"], "a": 1, "e": "Die hufeisenförmigen Cartilagines tracheales sind dorsal offen; die Lücke schließt der Paries membranaceus mit M. trachealis."}, {"id": "anat-lunge-14", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "In welcher Höhe liegt die Bifurcatio tracheae, und welche Struktur entspricht ihr innen?", "o": ["Etwa Höhe Th4; innen die Carina tracheae", "Etwa Höhe Th8; innen die Carina tracheae", "Etwa Höhe C6; innen die Plica vocalis", "Etwa Höhe Th10; innen der Hiatus oesophageus"], "a": 0, "e": "Die Bifurkation liegt etwa auf Höhe Th4 (Angulus sterni); der innen vorspringende Sporn ist die Carina tracheae."}, {"id": "anat-lunge-15", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Aus welchem Nerv stammen die Rami tracheales, die die Trachea innervieren?", "o": ["Truncus sympathicus, Ganglion cervicale superius", "Nervus laryngeus superior, Ramus externus", "Nervus phrenicus aus dem Plexus cervicalis", "Nervus laryngeus recurrens (Nervus vagus)"], "a": 3, "e": "Die parasympathischen und sensiblen Rr. tracheales kommen aus dem N. laryngeus recurrens, einem Ast des N. vagus."}, {"id": "anat-lunge-16", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Welche Nervenäste bewirken eine Verengung der Bronchien?", "o": ["Rami pericardiaci des Nervus phrenicus", "Rami cardiaci des Nervus laryngeus recurrens", "Rami bronchiales des Truncus sympathicus", "Rami bronchiales des Nervus vagus"], "a": 3, "e": "Parasympathikus (N. vagus, Abgang distal des N. laryngeus recurrens) → Bronchokonstriktion und Sekretion; Sympathikus → Bronchodilatation."}, {"id": "anat-lunge-17", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Um welche Struktur schlingt sich der Nervus laryngeus recurrens sinister?", "o": ["Arcus aortae (lateral des Ligamentum arteriosum)", "Arteria pulmonalis sinistra am Lungenhilum", "Truncus brachiocephalicus vor der Trachea", "Arteria subclavia sinistra am Truncus thyrocervicalis"], "a": 0, "e": "Links umschlingt der Recurrens den Aortenbogen, rechts die A. subclavia dextra; dann steigt er in der Rinne zwischen Trachea und Ösophagus zum Kehlkopf auf."}, {"id": "anat-lunge-18", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Um welche Struktur schlingt sich der Nervus laryngeus recurrens dexter?", "o": ["Truncus brachiocephalicus", "Arteria carotis communis dextra", "Arteria subclavia dextra", "Arcus venae azygos"], "a": 2, "e": "Wegen der tieferen Umschlingung links ist der linke Recurrens länger und z. B. durch Aortenaneurysma oder Bronchialkarzinom gefährdet (Heiserkeit)."}, {"id": "anat-lunge-19", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Welcher Nerv innerviert die Pleura mediastinalis sensibel?", "o": ["Nervus phrenicus", "Truncus sympathicus", "Nervus vagus", "Nervi intercostales"], "a": 0, "e": "N. phrenicus (C3–C5): Pleura mediastinalis, zentrale Pleura diaphragmatica, Perikard; Pleura costalis und periphere Pleura diaphragmatica: Nn. intercostales. Pleura visceralis ist schmerzunempfindlich."}, {"id": "anat-lunge-20", "ch": "2 Lunge, Trachea, Bronchien, Mediastinum", "q": "Welche Fissur trennt in der rechten Lunge Ober- und Mittellappen?", "o": ["Fissura horizontalis", "Fissura obliqua", "Sulcus venae azygos", "Incisura cardiaca"], "a": 0, "e": "Rechts: Fissura obliqua (Unterlappen von Ober- und Mittellappen) und Fissura horizontalis; links nur Fissura obliqua. Die Lappenflächen heißen Facies interlobares."}, {"id": "anat-magen-01", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Wo liegen die drei physiologischen Ösophagusengen?", "o": ["Ringknorpel, Herzbeutel, Ligamentum arteriosum", "Ringknorpel, Aortenbogen, Hiatus oesophageus", "Schildknorpel, Arcus venae azygos, Pylorus", "Zungenbein, Bifurcatio tracheae, Kardia"], "a": 1, "e": "Obere Enge (C6, hinter Cartilago cricoidea), mittlere Enge (Aortenbogen/linker Hauptbronchus, ca. Th4), untere Enge (Zwerchfelldurchtritt, ca. Th10). Hier bleiben Fremdkörper und Tabletten hängen."}, {"id": "anat-magen-02", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Wie weit ist der Mageneingang ungefähr von der vorderen Zahnreihe entfernt, und wofür ist das relevant?", "o": ["Ca. 60 cm; Länge einer Magensonde bis Pylorus", "Ca. 15 cm; Abstand bis zur Bifurcatio tracheae", "Ca. 40 cm; Orientierung bei der Gastroskopie", "Ca. 25 cm; Orientierung bei der Gastroskopie"], "a": 2, "e": "Ösophagusbeginn ca. 15 cm, mittlere Enge ca. 25 cm, Kardia ca. 40 cm ab Zahnreihe; der Ösophagus selbst ist ca. 25 cm lang."}, {"id": "anat-magen-03", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Welche Arterie versorgt den oberen (zervikalen) Anteil des Ösophagus?", "o": ["Arteria thyroidea inferior", "Arteria phrenica inferior", "Arteria gastrica sinistra", "Arteria thoracica interna"], "a": 0, "e": "Pars cervicalis: A. thyroidea inferior (Truncus thyrocervicalis); Pars thoracica: Rr. oesophageales der Aorta thoracica; Pars abdominalis: A. gastrica sinistra und A. phrenica inferior."}, {"id": "anat-magen-04", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Woher bezieht die Pars thoracica des Ösophagus hauptsächlich ihre arterielle Versorgung?", "o": ["Rami oesophageales der Arteria thyroidea inferior", "Rami tracheales der Arteria thoracica interna", "Rami oesophageales der Arteria gastrica sinistra", "Rami oesophageales der Aorta thoracica"], "a": 3, "e": "Die segmentalen Rr. oesophageales kommen direkt aus der Aorta thoracica, ergänzt durch Rr. bronchiales."}, {"id": "anat-magen-05", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Welcher Mechanismus gehört zum funktionellen Verschluss am Übergang von Ösophagus zu Magen?", "o": ["Spitzer His-Winkel an der Incisura cardialis", "Quergestreifter Musculus cricopharyngeus", "Kontraktion des Musculus sphincter pyloricus", "Muskelring aus dem Stratum longitudinale"], "a": 0, "e": "Bestandteile: spiralige Wandmuskulatur (Wringmechanismus), Zwerchfellschenkel am Hiatus, His-Winkel, Venenpolster der Submukosa, Lig. phrenicooesophageale, Druckgradient Thorax/Abdomen. Versagen → Reflux, Barrett-Ösophagus."}, {"id": "anat-magen-06", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Welche Struktur befestigt den Ösophagus am Zwerchfell?", "o": ["Ligamentum arcuatum medianum (Aortenbogen)", "Ligamentum gastrophrenicum (Magenfixierung)", "Ligamentum phrenicooesophageale (Laimer-Membran)", "Ligamentum hepatogastricum (Omentum minus)"], "a": 2, "e": "Die Laimer-Membran fixiert den Ösophagus elastisch im Hiatus oesophageus; ihre Lockerung begünstigt die axiale Hiatushernie."}, {"id": "anat-magen-07", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Aus welchem Nervus vagus geht hauptsächlich der Truncus vagalis anterior hervor?", "o": ["Aus dem Truncus sympathicus", "Aus dem rechten Nervus vagus", "Aus dem linken Nervus vagus", "Aus dem Nervus phrenicus"], "a": 2, "e": "Durch die Magendrehung gelangt der linke Vagus nach vorn (Truncus vagalis anterior), der rechte nach hinten (posterior); beide entstehen aus dem Plexus oesophageus."}, {"id": "anat-magen-08", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Welcher Nerv innerviert den Magen parasympathisch?", "o": ["Nervus splanchnicus pelvicus", "Nervus splanchnicus major", "Nervus vagus (Trunci vagales)", "Nervus phrenicus dexter"], "a": 2, "e": "Über die Trunci vagales: Steigerung von Motilität und Säuresekretion. Sympathisch: N. splanchnicus major über Ganglia coeliaca."}, {"id": "anat-magen-09", "ch": "3 Ösophagus, Magen, Duodenum", "q": "In welchem Magenabschnitt ist im Röntgenbild im Stehen die Magenblase sichtbar?", "o": ["Antrum pyloricum", "Pars cardiaca", "Fundus gastricus", "Corpus gastricum"], "a": 2, "e": "Der Fundus ist der höchste Magenabschnitt unter der linken Zwerchfellkuppel; hier sammelt sich Luft."}, {"id": "anat-magen-10", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Welche Struktur der kleinen Kurvatur trennt Corpus und Pars pylorica, also zwei funktionell unterschiedliche Teile?", "o": ["Incisura cardialis", "Ostium cardiacum", "Canalis pyloricus", "Incisura angularis"], "a": 3, "e": "Proximal (Fundus/Corpus): Speicher und Säurebildung; distal (Pars pylorica): Durchmischung und Entleerung."}, {"id": "anat-magen-11", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Wie heißen die längs gerichteten Schleimhautfalten an der Curvatura minor?", "o": ["Plicae semilunares", "Plicae transversae", "Die Magenstraße", "Kerckring-Falten"], "a": 2, "e": "Die Plicae gastricae verlaufen an der kleinen Kurvatur längs und leiten Flüssigkeit rasch zum Pylorus."}, {"id": "anat-magen-12", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Wo liegt das Stratum longitudinale der Magenmuskulatur?", "o": ["Außen, verstärkt an den Kurvaturen", "Innen, verstärkt an der Kardia", "Innen, verstärkt am Fundus", "In der Mitte, verstärkt am Pylorus"], "a": 0, "e": "Schichten von außen nach innen: Stratum longitudinale, Stratum circulare (bildet den M. sphincter pyloricus), Fibrae obliquae."}, {"id": "anat-magen-13", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Wie heißt der spitze Winkel zwischen Ösophagus und Fundus an der Incisura cardialis?", "o": ["Louis-Winkel", "Calot-Winkel", "Treitz-Winkel", "His-Winkel"], "a": 3, "e": "Der His-Winkel wirkt ventilartig gegen Reflux; Treitz betrifft die Flexura duodenojejunalis, der Angulus sterni (Louis) das Sternum."}, {"id": "anat-magen-14", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Wie heißt der Abschnitt zwischen Antrum pyloricum und Pylorus?", "o": ["Canalis pyloricus", "Pars cardiaca", "Bulbus duodeni", "Incisura angularis"], "a": 0, "e": "Pars pylorica = Antrum pyloricum + Canalis pyloricus + Pylorus (mit M. sphincter pyloricus), danach Bulbus duodeni."}, {"id": "anat-magen-15", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Welche Arterien versorgen die Curvatura minor?", "o": ["Arteriae gastroomentales dextra und sinistra", "Arteriae gastricae breves und posterior", "Arteriae pancreaticoduodenales superiores", "Arteriae gastricae sinistra und dextra"], "a": 3, "e": "A. gastrica sinistra (Truncus coeliacus) und A. gastrica dextra (meist A. hepatica propria) bilden an der kleinen Kurvatur einen Gefäßbogen im Omentum minus."}, {"id": "anat-magen-16", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Welche Arterie versorgt die große Kurvatur von rechts und aus welchem Gefäß stammt sie?", "o": ["Arteria gastroomentalis dextra aus der Arteria mesenterica superior", "Arteria gastrica dextra aus der Arteria gastroduodenalis", "Arteria gastroomentalis dextra aus der Arteria gastroduodenalis", "Arteria gastroomentalis dextra aus der Arteria hepatica propria"], "a": 2, "e": "Die A. gastroomentalis dextra anastomosiert an der großen Kurvatur mit der A. gastroomentalis sinistra und gibt Rr. omentales zum Omentum majus."}, {"id": "anat-magen-17", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Aus welchem Gefäß stammt die Arteria gastroomentalis sinistra?", "o": ["Arteria gastrica sinistra", "Arteria splenica", "Arteria gastroduodenalis", "Arteria hepatica communis"], "a": 1, "e": "Die A. splenica gibt nahe dem Milzhilum die A. gastroomentalis sinistra und die Aa. gastricae breves ab."}, {"id": "anat-magen-18", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Welche Gefäße versorgen Kardia und Fundus des Magens?", "o": ["Arteria gastrica dextra, Arteria gastroduodenalis, Arteria gastroomentalis dextra", "Arteria hepatica propria, Arteria cystica, Arteria pancreaticoduodenalis", "Arteria gastrica sinistra, Arteriae gastricae breves, Arteria gastrica posterior", "Arteria mesenterica superior, Arteria colica media, Arteriae jejunales"], "a": 2, "e": "Aa. gastricae breves und A. gastrica posterior stammen aus der A. splenica; die A. gastrica sinistra gibt zusätzlich Rr. oesophageales ab."}, {"id": "anat-magen-19", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Aus welcher Arterie entspringt die Arteria gastrica sinistra?", "o": ["Arteria splenica", "Arteria gastroduodenalis", "Truncus coeliacus", "Arteria hepatica propria"], "a": 2, "e": "Der Truncus coeliacus (ca. Th12/L1) teilt sich in A. gastrica sinistra, A. hepatica communis und A. splenica (Haller-Dreifuß)."}, {"id": "anat-magen-20", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Welcher Abschnitt des Duodenums liegt intraperitoneal?", "o": ["Pars ascendens duodeni", "Pars descendens duodeni", "Pars horizontalis duodeni", "Pars superior duodeni"], "a": 3, "e": "Die Pars superior (Ampulle) ist intraperitoneal und beweglich; die übrigen Abschnitte liegen sekundär retroperitoneal. Häufigster Ort des Ulcus duodeni."}, {"id": "anat-magen-21", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Welche Struktur wirft die Plica longitudinalis duodeni auf, und wo endet sie?", "o": ["Ductus pancreaticus accessorius; Papilla minor", "Ductus choledochus; Papilla duodeni major", "Ductus cysticus; Flexura duodeni superior", "Arteria gastroduodenalis; Bulbus duodeni"], "a": 1, "e": "In der Pars descendens hinten-medial wird die Längsfalte vom intramural verlaufenden Ductus choledochus erzeugt; an der Papilla duodeni major (Vater) münden Ductus choledochus und Ductus pancreaticus."}, {"id": "anat-magen-22", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Welcher Darmabschnitt ist am Musculus suspensorius duodeni (Treitz-Band) aufgehängt?", "o": ["Flexura coli sinistra", "Flexura duodeni inferior", "Flexura duodenojejunalis", "Pars superior duodeni"], "a": 2, "e": "Der Treitz-Muskel zieht vom Bindegewebe um Truncus coeliacus/A. mesenterica superior zur Flexura duodenojejunalis; Grenze oberer/unterer GI-Blutung."}, {"id": "anat-magen-23", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Welcher Abschnitt des Duodenums wird beim Arteria-mesenterica-superior-Syndrom (Wilkie-Syndrom) eingeengt?", "o": ["Pars descendens duodeni", "Pars superior duodeni", "Pars horizontalis duodeni", "Flexura duodenojejunalis"], "a": 2, "e": "Die Pars horizontalis verläuft zwischen Aorta (dorsal) und A. mesenterica superior (ventral); ein spitzer Abgangswinkel (z. B. bei starkem Gewichtsverlust) führt zur Duodenalobstruktion."}, {"id": "anat-magen-24", "ch": "3 Ösophagus, Magen, Duodenum", "q": "Auf welchem Weg metastasiert ein Magenkarzinom hämatogen am ehesten?", "o": ["Über die Vena azygos in die Wirbelsäule", "Über die Vena cava inferior in die Lunge", "Über die Vena renalis in die Niere", "Über die Vena portae in die Leber"], "a": 3, "e": "Das venöse Magenblut fließt über Vv. gastricae, gastroomentales und V. splenica in die Pfortader; die Leber ist daher erste Filterstation. Lymphogen: Nll. gastrici entlang der Kurvaturen."}, {"id": "anat-darm-01", "ch": "4 Dünn- und Dickdarm", "q": "Welche Taenie dient intraoperativ als Wegweiser zur Appendix vermiformis?", "o": ["Taenia mesocolica", "Taenia libera", "Taenia omentalis", "Plica semilunaris"], "a": 1, "e": "Alle drei Taenien laufen an der Appendixbasis zusammen; die frei sichtbare Taenia libera ist am leichtesten zu verfolgen."}, {"id": "anat-darm-02", "ch": "4 Dünn- und Dickdarm", "q": "Welche Struktur gibt der Taenia mesocolica ihren Namen?", "o": ["Radix mesenterii", "Mesocolon transversum", "Mesocolon sigmoideum", "Ligamentum gastrocolicum"], "a": 1, "e": "Am Colon transversum setzt das Mesocolon transversum an der Taenia mesocolica an."}, {"id": "anat-darm-03", "ch": "4 Dünn- und Dickdarm", "q": "Welche Struktur gibt der Taenia omentalis ihren Namen?", "o": ["Radix mesenterii", "Omentum majus", "Mesoappendix", "Omentum minus"], "a": 1, "e": "Am Colon transversum ist das Omentum majus an der Taenia omentalis angeheftet."}, {"id": "anat-darm-04", "ch": "4 Dünn- und Dickdarm", "q": "Welches Merkmal am Kolon entsteht durch das Stratum circulare der Tunica muscularis?", "o": ["Plicae circulares", "Plicae semilunares", "Die Taeniae coli", "Appendices epiploicae"], "a": 1, "e": "Kontraktionen der Ringmuskulatur erzeugen die Plicae semilunares und dazwischen die Haustren; Taenien sind Verdichtungen des Stratum longitudinale."}, {"id": "anat-darm-05", "ch": "4 Dünn- und Dickdarm", "q": "Welches makroskopische Merkmal kommt am Kolon, aber nicht am Dünndarm vor?", "o": ["Mesenterium mit Arkaden", "Peyer-Plaques", "Appendices epiploicae", "Plicae circulares"], "a": 2, "e": "Kolonmerkmale: Taeniae coli, Haustra coli mit Plicae semilunares, Appendices epiploicae (Fettanhängsel)."}, {"id": "anat-darm-06", "ch": "4 Dünn- und Dickdarm", "q": "Wo findet man Peyer-Plaques am ehesten?", "o": ["Im distalen Ileum, antimesenterial", "Im Colon ascendens an der Taenia", "Im Duodenum an der Papilla major", "Im proximalen Jejunum, mesenterial"], "a": 0, "e": "Peyer-Plaques (Folliculi lymphoidei aggregati) liegen gegenüber dem Mesenterialansatz v. a. im terminalen Ileum."}, {"id": "anat-darm-07", "ch": "4 Dünn- und Dickdarm", "q": "Wo bildet sich ein Meckel-Divertikel, und wovon ist es ein Rest?", "o": ["Colon; Rest des Urachus", "Jejunum; Rest des Ductus venosus", "Duodenum; Rest des Ductus arteriosus", "Ileum; Rest des Ductus omphaloentericus"], "a": 3, "e": "Faustregel: ca. 2 % der Bevölkerung, ca. 60–100 cm proximal der Ileozäkalklappe, evtl. mit ektoper Magenschleimhaut (Blutung)."}, {"id": "anat-darm-08", "ch": "4 Dünn- und Dickdarm", "q": "Aus welchen Lippen besteht die Papilla ilealis (Bauhin-Klappe)?", "o": ["Frenulum ostii und Taenia libera", "Labrum ileocaecale und Plica semilunaris", "Labrum ileocolicum und Plica circularis", "Labrum ileocolicum und Labrum ileocaecale"], "a": 3, "e": "Das Ostium ileale liegt auf der Papilla ilealis; die Lippen setzen sich seitlich als Frenula ostii ilealis fort und hemmen den Rückfluss ins Ileum."}, {"id": "anat-darm-09", "ch": "4 Dünn- und Dickdarm", "q": "Aus welchem Gefäß entspringt die Arteria ileocolica?", "o": ["Arteria mesenterica superior", "Arteria iliaca interna", "Truncus coeliacus", "Arteria mesenterica inferior"], "a": 0, "e": "Die A. ileocolica versorgt terminales Ileum, Zäkum und über die A. appendicularis die Appendix."}, {"id": "anat-darm-10", "ch": "4 Dünn- und Dickdarm", "q": "Welches Kolonsegment versorgt die Arteria colica media, und wo verläuft sie?", "o": ["Colon ascendens; retroperitoneal", "Colon sigmoideum; im Mesocolon sigmoideum", "Colon descendens; retroperitoneal", "Colon transversum; im Mesocolon transversum"], "a": 3, "e": "Die A. colica media (aus der A. mesenterica superior) anastomosiert über die Riolan-Anastomose mit der A. colica sinistra (aus der A. mesenterica inferior)."}, {"id": "anat-darm-11", "ch": "4 Dünn- und Dickdarm", "q": "Aus welchem Gefäß stammt die Arteria colica sinistra?", "o": ["Arteria colica media", "Arteria iliaca communis", "Arteria mesenterica superior", "Arteria mesenterica inferior"], "a": 3, "e": "Die A. mesenterica inferior (Höhe L3) gibt A. colica sinistra, Aa. sigmoideae und A. rectalis superior ab."}, {"id": "anat-darm-12", "ch": "4 Dünn- und Dickdarm", "q": "Aus welchem Gefäß stammt die Arteria colica dextra?", "o": ["Arteria mesenterica inferior", "Arteria mesenterica superior", "Arteria gastroduodenalis", "Arteria iliaca externa"], "a": 1, "e": "Rechte Kolonhälfte bis ca. linkes Drittel des Transversums: A. mesenterica superior; danach A. mesenterica inferior (Cannon-Böhm-Punkt)."}, {"id": "anat-darm-13", "ch": "4 Dünn- und Dickdarm", "q": "Aus welchem Gefäß gehen die Arteriae jejunales und ileales ab?", "o": ["Arteria mesenterica inferior", "Truncus coeliacus", "Arteria mesenterica superior", "Arteria ileocolica"], "a": 2, "e": "Sie verlaufen im Mesenterium, bilden Arkaden und enden als Vasa recta; im Jejunum wenige Arkaden mit langen Vasa recta, im Ileum mehr Arkadenreihen."}, {"id": "anat-darm-14", "ch": "4 Dünn- und Dickdarm", "q": "Welche Kolonflexur liegt höher, und mit welchem Band ist sie am Zwerchfell befestigt?", "o": ["Flexura coli dextra; Ligamentum hepatocolicum", "Flexura coli dextra; Ligamentum phrenicocolicum", "Flexura coli sinistra; Ligamentum phrenicocolicum", "Flexura coli sinistra; Ligamentum gastrocolicum"], "a": 2, "e": "Die linke Flexur liegt am Milzpol höher als die rechte (unter der Leber); das Lig. phrenicocolicum bildet einen Boden für die Milz."}, {"id": "anat-darm-15", "ch": "4 Dünn- und Dickdarm", "q": "Welcher Kolonabschnitt liegt intraperitoneal mit eigenem Mesocolon im kleinen Becken?", "o": ["Colon descendens", "Rectum (Ampulla)", "Colon ascendens", "Colon sigmoideum"], "a": 3, "e": "Intraperitoneal: Colon transversum und sigmoideum; sekundär retroperitoneal: Colon ascendens und descendens."}, {"id": "anat-darm-16", "ch": "4 Dünn- und Dickdarm", "q": "Eine Entzündung welches Organs kann Schmerzen bei Anspannung des Musculus iliopsoas auslösen (Psoaszeichen)?", "o": ["Appendix vermiformis", "Pars superior duodeni", "Flexura coli sinistra", "Gallenblase (Fundus)"], "a": 0, "e": "Eine retrozäkale Appendizitis reizt das parietale Peritoneum über dem M. psoas; über diesen Muskel können sich retroperitoneale Entzündungen bis zum Oberschenkel ausbreiten."}, {"id": "anat-darm-17", "ch": "4 Dünn- und Dickdarm", "q": "In welche Vene fließt die Vena rectalis superior, und warum ist das klinisch relevant?", "o": ["Vena mesenterica inferior; portokavale Anastomose", "Vena pudenda interna; Hämorrhoidalthrombose", "Vena iliaca interna; direkter Abfluss zur Cava", "Vena mesenterica superior; Mesenterialinfarkt"], "a": 0, "e": "V. rectalis superior → V. mesenterica inferior → V. portae; Vv. rectales media und inferior → V. iliaca interna → V. cava inferior. Bei portaler Hypertension Umgehungskreislauf im Rektum; Rektumkarzinom metastasiert so in Leber bzw. Lunge."}, {"id": "anat-darm-18", "ch": "4 Dünn- und Dickdarm", "q": "Wohin mündet die Vena mesenterica inferior meist?", "o": ["In die Vena iliaca communis", "In die Vena splenica", "In die Vena renalis sinistra", "In die Vena cava inferior"], "a": 1, "e": "Die V. splenica vereinigt sich hinter dem Pankreashals mit der V. mesenterica superior zur V. portae hepatis."}, {"id": "anat-darm-19", "ch": "4 Dünn- und Dickdarm", "q": "Wo kommen Plicae circulares (Kerckring-Falten) am dichtesten vor?", "o": ["Im Antrum des Magens", "Im terminalen Ileum", "Im proximalen Jejunum", "Im Colon transversum"], "a": 2, "e": "Kerckring-Falten (Mukosa + Submukosa) vergrößern die Oberfläche; sie nehmen nach distal ab und fehlen im Kolon."}, {"id": "anat-leber-01", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Welche obliterierte fetale Struktur enthält das Ligamentum teres hepatis?", "o": ["Vena umbilicalis", "Ductus arteriosus", "Arteria umbilicalis", "Ductus venosus"], "a": 0, "e": "Das Lig. teres hepatis zieht im freien Rand des Lig. falciforme zum Nabel; bei portaler Hypertension können paraumbilikale Venen (Caput medusae) rekanalisieren."}, {"id": "anat-leber-02", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Welche Struktur enthält den obliterierten Ductus venosus (Arantii)?", "o": ["Ligamentum coronarium", "Ligamentum venosum", "Ligamentum teres hepatis", "Ligamentum triangulare"], "a": 1, "e": "Das Lig. venosum liegt in der Fissura ligamenti venosi zwischen Lobus caudatus und Lobus sinister; fetal umging der Ductus venosus die Leber."}, {"id": "anat-leber-03", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Was trennt die Leber funktionell in eine rechte und eine linke Hälfte?", "o": ["Linie vom Ligamentum venosum zum Lobus caudatus", "Linie von der unteren Hohlvene zum Gallenblasenfundus", "Ligamentum falciforme und Fissura ligamenti teretis", "Ligamentum coronarium und Area nuda der Leber"], "a": 1, "e": "Die Cantlie-Linie (mit der V. hepatica media) teilt nach Versorgungsgebieten von A. hepatica propria und V. portae; das Lig. falciforme trennt nur die anatomischen Lappen."}, {"id": "anat-leber-04", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Welche Anteile gehören zum funktionellen rechten Leberlappen?", "o": ["Lobus dexter und rechter Teil des Lobus caudatus", "Lobus quadratus und linker Lobus caudatus", "Lobus dexter allein ohne Lobus caudatus", "Lobus dexter und Lobus quadratus komplett"], "a": 0, "e": "Der Lobus quadratus gehört funktionell zum linken Lappen (Segment IV); der Lobus caudatus (Segment I) wird von beiden Seiten versorgt."}, {"id": "anat-leber-05", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Aus welchen Leberanteilen sammelt der Ductus hepaticus dexter die Galle?", "o": ["Lobus dexter und rechter Teil des Lobus caudatus", "Ausschließlich aus dem Lobus caudatus", "Lobus dexter und Lobus quadratus", "Lobus sinister und Lobus quadratus"], "a": 0, "e": "Ductus hepaticus dexter und sinister vereinigen sich zum Ductus hepaticus communis; der sinister drainiert Lobus sinister, Lobus quadratus und linken Caudatus-Anteil."}, {"id": "anat-leber-06", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Welche Strukturen verbinden den Lobus caudatus mit dem Lobus dexter der Leber?", "o": ["Processus caudatus (und Ligamentum venae cavae)", "Ligamentum triangulare und Appendix fibrosa", "Ligamentum falciforme und Lobus quadratus", "Ligamentum venosum und Fissura ligamenti teretis"], "a": 0, "e": "Der Processus caudatus zieht zwischen V. cava inferior und Porta hepatis zum rechten Lappen; das Lig. venae cavae überbrückt die Hohlvene dorsal."}, {"id": "anat-leber-07", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Zwischen welchen Strukturen liegt der Lobus quadratus der Leber?", "o": ["Vena cava inferior und Ligamentum venosum", "Gallenblase und Ligamentum teres hepatis", "Ligamentum falciforme und Area nuda", "Porta hepatis und Vena cava inferior"], "a": 1, "e": "Lobus quadratus: vor der Porta hepatis zwischen Fossa vesicae biliaris und Fissura ligamenti teretis; Lobus caudatus: hinter der Porta zwischen V. cava und Lig. venosum."}, {"id": "anat-leber-08", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Welche Struktur begrenzt die Area nuda der Leber?", "o": ["Ligamentum falciforme", "Ligamentum hepatoduodenale", "Ligamentum coronarium", "Ligamentum teres hepatis"], "a": 2, "e": "Die Area nuda ist peritonealfrei und mit dem Zwerchfell verwachsen; das Lig. coronarium läuft seitlich in die Ligg. triangularia aus."}, {"id": "anat-leber-09", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Wo liegt die Appendix fibrosa hepatis?", "o": ["Am Processus caudatus hinten", "Am Unterrand des Lobus quadratus", "An der Spitze des linken Leberlappens", "Am Fundus der Gallenblase"], "a": 2, "e": "Die Appendix fibrosa ist ein bindegewebiger Fortsatz am Ende des Lig. triangulare sinistrum, Rest zurückgebildeten Lebergewebes."}, {"id": "anat-leber-10", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Welches Gefäß führt etwa drei Viertel des Leberblutes zu, und wie nennt man es funktionell?", "o": ["Vena portae hepatis; Vas privatum", "Arteria hepatica propria; Vas publicum", "Arteria hepatica propria; Vas privatum", "Vena portae hepatis; Vas publicum"], "a": 3, "e": "Die Pfortader bringt nährstoffreiches Blut zur Verarbeitung für den Gesamtorganismus (Vas publicum); die A. hepatica propria (ca. 25 %) versorgt die Leber selbst (Vas privatum)."}, {"id": "anat-leber-11", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Welches ist das größte Gefäß, das durch die Porta hepatis zieht?", "o": ["Arteria hepatica propria", "Ductus hepaticus communis", "Vena cava inferior", "Vena portae hepatis"], "a": 3, "e": "In der Porta hepatis: V. portae (dorsal), A. hepatica propria (links-ventral), Ductus hepaticus (rechts-ventral). Die Vv. hepaticae verlassen die Leber dagegen hinten direkt zur V. cava inferior."}, {"id": "anat-leber-12", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Wohin münden die Venae hepaticae?", "o": ["In den rechten Vorhof über eigene Ostien", "In die Vena portae hepatis an der Leberpforte", "In die Vena azygos im hinteren Mediastinum", "In die Vena cava inferior unter dem Zwerchfell"], "a": 3, "e": "Drei Vv. hepaticae (dextra, media, sinistra) münden an der Area nuda in die V. cava inferior kurz vor deren Durchtritt durch das Centrum tendineum."}, {"id": "anat-leber-13", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Welche drei Arterien entspringen aus dem Truncus coeliacus?", "o": ["Arteria gastrica sinistra, hepatica communis, splenica", "Arteria gastroduodenalis, hepatica communis, splenica", "Arteria gastrica sinistra, gastroduodenalis, cystica", "Arteria gastrica dextra, hepatica propria, splenica"], "a": 0, "e": "Der Truncus coeliacus versorgt die Oberbauchorgane (Vorderdarm): Magen, Duodenum oral der Papille, Leber, Galle, Pankreas (teilweise), Milz."}, {"id": "anat-leber-14", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "In welche zwei Äste teilt sich die Arteria hepatica communis?", "o": ["Arteria gastrica dextra und Arteria gastroduodenalis", "Arteria hepatica propria und Arteria gastrica sinistra", "Ramus dexter und Ramus sinister der Leberarterie", "Arteria hepatica propria und Arteria gastroduodenalis"], "a": 3, "e": "Die A. hepatica propria zieht im Lig. hepatoduodenale zur Leber und teilt sich in R. dexter und R. sinister; die A. gastroduodenalis zieht hinter das Duodenum."}, {"id": "anat-leber-15", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Aus welchem Gefäß entspringt die Arteria cystica in der Regel?", "o": ["Ramus dexter der Arteria hepatica propria", "Arteria mesenterica superior", "Ramus sinister der Arteria hepatica propria", "Arteria gastroduodenalis"], "a": 0, "e": "Die A. cystica entspringt meist aus dem R. dexter (A. hepatica dextra); Varianten wie eine doppelte A. cystica sind bei der Cholezystektomie zu beachten."}, {"id": "anat-leber-16", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Welche Struktur liegt im Calot-Dreieck?", "o": ["Arteria gastroduodenalis", "Arteria cystica", "Vena portae hepatis", "Ductus pancreaticus"], "a": 1, "e": "Calot-Dreieck: Ductus cysticus, Ductus hepaticus communis, Leberunterfläche; die A. cystica wird hier bei der Cholezystektomie aufgesucht und ligiert."}, {"id": "anat-leber-17", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Aus welchen Gängen entsteht der Ductus choledochus?", "o": ["Ductus hepaticus dexter und Ductus hepaticus sinister", "Ductus cysticus und Ductus hepaticus communis", "Ductus cysticus und Ductus pancreaticus major", "Ductus hepaticus communis und Ductus pancreaticus"], "a": 1, "e": "Der Ductus choledochus verläuft im Lig. hepatoduodenale, hinter der Pars superior duodeni und durch den Pankreaskopf zur Papilla duodeni major."}, {"id": "anat-leber-18", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Wie heißen die Abschnitte der Gallenblase von distal nach proximal?", "o": ["Collum, Corpus, Fundus", "Corpus, Fundus, Collum", "Fundus, Corpus, Collum", "Fundus, Collum, Corpus"], "a": 2, "e": "Der Fundus überragt den Leberunterrand (Projektion: Medioklavikularlinie/9. Rippenknorpel); das Collum geht in den Ductus cysticus mit Plica spiralis über."}, {"id": "anat-leber-19", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Aus welchem Gefäß stammen die Rami pancreatici?", "o": ["Arteria gastroduodenalis", "Arteria hepatica propria", "Arteria gastrica sinistra", "Arteria splenica (lienalis)"], "a": 3, "e": "Die A. splenica verläuft geschlängelt am Oberrand des Pankreas und gibt die Rr. pancreatici sowie die A. pancreatica dorsalis und magna ab."}, {"id": "anat-leber-20", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Aus welchem Gefäß entspringt die Arteria pancreaticoduodenalis superior posterior?", "o": ["Arteria mesenterica superior", "Arteria gastrica dextra", "Arteria hepatica propria", "Arteria gastroduodenalis"], "a": 3, "e": "Aa. pancreaticoduodenales superiores (aus A. gastroduodenalis) und inferiores (aus A. mesenterica superior) bilden Arkaden um den Pankreaskopf."}, {"id": "anat-leber-21", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Welches Gefäß gibt die Arteria pancreaticoduodenalis inferior ab?", "o": ["Arteria hepatica communis", "Arteria mesenterica superior", "Arteria mesenterica inferior", "Arteria gastroduodenalis"], "a": 1, "e": "Die Pankreaskopfarkaden verbinden Truncus coeliacus und A. mesenterica superior – wichtiger Kollateralkreislauf."}, {"id": "anat-leber-22", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Welcher Pankreasabschnitt liegt nicht sekundär retroperitoneal, sondern reicht im Ligamentum splenorenale bis zum Milzhilum?", "o": ["Processus uncinatus", "Cauda pancreatis", "Collum pancreatis", "Caput pancreatis"], "a": 1, "e": "Kopf, Hals und Körper liegen sekundär retroperitoneal; die Cauda liegt im Lig. splenorenale intraperitoneal nahe Milzhilum und Flexura coli sinistra."}, {"id": "anat-leber-23", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Welche Organe berühren die Milz an ihrer Facies colica bzw. am Hilum?", "o": ["Colon sigmoideum bzw. linke Nebenniere", "Flexura coli dextra bzw. Caput pancreatis", "Flexura coli sinistra bzw. Cauda pancreatis", "Pars superior duodeni bzw. Fundus gastricus"], "a": 2, "e": "Weitere Kontaktflächen: Facies gastrica (Magen), Facies renalis (linke Niere)."}, {"id": "anat-leber-24", "ch": "5 Leber, Galle, Pankreas, Milz", "q": "Was ist das Besondere an der Arteria splenica?", "o": ["Gerader Verlauf; bildet Arkaden wie Jejunalgefäße", "Intraperitonealer Verlauf im Ligamentum gastrocolicum", "Geschlängelter Verlauf; teilt sich in Segmentarterien", "Entspringt meist direkt aus der Aorta über dem Truncus"], "a": 2, "e": "Die Schlängelung erlaubt Bewegungen von Magen/Milz; die Segmentarterien sind funktionelle Endarterien (keilförmige Milzinfarkte)."}, {"id": "anat-zwf-01", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Aus welcher Arterie stammen die Vasa pericardiacophrenica?", "o": ["Aorta pars thoracica", "Arteria thoracica interna", "Arteria subclavia (direkt)", "Arteria phrenica inferior"], "a": 1, "e": "Die A. pericardiacophrenica begleitet den N. phrenicus zwischen Perikard und Pleura mediastinalis zum Zwerchfell."}, {"id": "anat-zwf-02", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Welcher Nerv innerviert das Zwerchfell motorisch?", "o": ["Nervus accessorius (Hirnnerv XI)", "Nervus phrenicus (C3–C5)", "Nervi intercostales (Th6–Th12)", "Nervus vagus (Hirnnerv X)"], "a": 1, "e": "Merkspruch 'C3, 4, 5 keeps the diaphragm alive'; Läsion → Zwerchfellhochstand. Sensibel versorgt er zusätzlich Perikard, Pleura mediastinalis und zentrales Zwerchfellperitoneum (inkl. Leberkapsel) – daher Schulterschmerz."}, {"id": "anat-zwf-03", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Was tritt durch das Trigonum sternocostale (Larrey-Spalte)?", "o": ["Nervus splanchnicus major", "Nervus phrenicus sinister", "Vasa epigastrica superiora", "Vena azygos und Ductus thoracicus"], "a": 2, "e": "Das Trigonum sternocostale liegt zwischen Pars sternalis und Pars costalis; es ist eine Bruchpforte für Zwerchfellhernien."}, {"id": "anat-zwf-04", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Wo tritt die Vena cava inferior durch das Zwerchfell?", "o": ["Foramen venae cavae im Centrum tendineum (Th8)", "Trigonum lumbocostale zwischen den Muskelteilen", "Hiatus aorticus hinter dem Ligamentum arcuatum (Th12)", "Hiatus oesophageus in der Pars lumbalis (Th10)"], "a": 0, "e": "Merkhilfe: I 8 (V. cava, Th8) 10 (Ösophagus, Th10) Eggs (Aorta, Th12). Im Centrum tendineum wird die Vene bei Inspiration offengehalten."}, {"id": "anat-zwf-05", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Welche Struktur überbrückt den Hiatus aorticus des Zwerchfells?", "o": ["Ligamentum arcuatum medianum", "Ligamentum phrenicooesophageale", "Ligamentum arcuatum laterale", "Ligamentum phrenicocolicum"], "a": 0, "e": "Das Lig. arcuatum medianum verbindet Crus dextrum und sinistrum der Pars lumbalis auf Höhe Th12; durch den Hiatus ziehen Aorta und Ductus thoracicus."}, {"id": "anat-zwf-06", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Welche Zwerchfellanteile werden nach ihrem Ursprung unterschieden?", "o": ["Pars costalis, Pars tendinea, Pars abdominalis", "Pars sternalis, Pars thoracica, Pars sacralis", "Pars sternalis, Pars costalis, Pars lumbalis", "Pars lumbalis, Pars vertebralis, Pars pelvina"], "a": 2, "e": "Alle Teile strahlen in das Centrum tendineum ein; die Pars lumbalis bildet mit Crus dextrum und sinistrum Hiatus aorticus und oesophageus."}, {"id": "anat-zwf-07", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Was enthält die Plica umbilicalis lateralis?", "o": ["Obliterierte Arteria umbilicalis", "Obliterierten Urachus", "Ligamentum teres hepatis", "Vasa epigastrica inferiora"], "a": 3, "e": "Lateral von ihr liegt die Fossa inguinalis lateralis (innerer Leistenring, indirekte Hernien), medial die Fossa inguinalis medialis (direkte Hernien)."}, {"id": "anat-zwf-08", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Welche Bauchfellfalte enthält die obliterierte Arteria umbilicalis?", "o": ["Plica umbilicalis mediana", "Plica umbilicalis medialis", "Plica umbilicalis lateralis", "Plica rectouterina"], "a": 1, "e": "Mediana: Urachus; medialis (paarig): obliterierte A. umbilicalis (Chorda arteriae umbilicalis); lateralis: Vasa epigastrica inferiora."}, {"id": "anat-zwf-09", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Wo verläuft der Urachus?", "o": ["In der Plica umbilicalis medialis", "In der Plica umbilicalis lateralis", "Im Ligamentum teres hepatis", "In der Plica umbilicalis mediana"], "a": 3, "e": "Der Urachus (Rest der Allantois) verbindet den Blasenscheitel mit dem Nabel; Persistenz → Urachusfistel/-zyste."}, {"id": "anat-zwf-10", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Welche Grube entspricht von innen dem Anulus inguinalis profundus?", "o": ["Anulus femoralis", "Fossa inguinalis medialis", "Fossa supravesicalis", "Fossa inguinalis lateralis"], "a": 3, "e": "Hier treten indirekte (laterale) Leistenhernien in den Leistenkanal ein, lateral der Vasa epigastrica inferiora."}, {"id": "anat-zwf-11", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Aus welchem Gefäß geht die Arteria epigastrica inferior ab?", "o": ["Arteria iliaca interna", "Arteria thoracica interna", "Arteria iliaca externa", "Arteria femoralis"], "a": 2, "e": "Sie entspringt kurz vor dem Leistenband und anastomosiert in der Rektusscheide mit der A. epigastrica superior (aus der A. thoracica interna)."}, {"id": "anat-zwf-12", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Welche Äste gibt die Aorta abdominalis parietal ab?", "o": ["Arteriae intercostales posteriores und bronchiales", "Truncus coeliacus, mesenterica superior, inferior", "Arteriae suprarenales mediae, renales, testiculares", "Arteriae phrenicae inferiores, lumbales, sacralis mediana"], "a": 3, "e": "Viszerale Äste: Truncus coeliacus, A. mesenterica superior/inferior (unpaar) sowie Aa. suprarenales mediae, renales, testiculares/ovaricae (paarig)."}, {"id": "anat-zwf-13", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Welche Vena brachiocephalica ist länger, und warum?", "o": ["Die linke, da sie vor dem Aortenbogen nach rechts zieht", "Die rechte, da sie hinter der Trachea verläuft", "Die linke, da sie die Vena azygos direkt aufnimmt", "Die rechte, da sie den Arcus venae azygos aufnimmt"], "a": 0, "e": "Beide Vv. brachiocephalicae (aus V. jugularis interna + V. subclavia im Venenwinkel) vereinigen sich rechts zur V. cava superior."}, {"id": "anat-zwf-14", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Wohin mündet die Vena thoracica interna?", "o": ["In die Vena cava inferior", "In die Vena azygos", "In die Vena brachiocephalica", "In die Vena subclavia lateral"], "a": 2, "e": "Sie begleitet die A. thoracica interna parasternal; die Arterie wird häufig als Bypassgefäß (LIMA/IMA) verwendet."}, {"id": "anat-zwf-15", "ch": "6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen", "q": "Welches dieser Organe liegt intraperitoneal?", "o": ["Colon transversum", "Colon ascendens", "Caput pancreatis", "Pars descendens duodeni"], "a": 0, "e": "Sekundär retroperitoneal: Duodenum (außer Pars superior), Pankreas (außer Cauda), Colon ascendens und descendens."}, {"id": "anat-niere-01", "ch": "7 Niere, Retroperitoneum, Becken", "q": "Welche Vene wird beim Nussknacker-Syndrom zwischen Aorta und Arteria mesenterica superior eingeklemmt?", "o": ["Vena mesenterica inferior", "Vena testicularis dextra", "Vena renalis sinistra", "Vena renalis dextra"], "a": 2, "e": "Die linke Nierenvene zieht vor der Aorta zur V. cava inferior; der Rückstau in die V. testicularis sinistra kann eine linksseitige Varikozele verursachen."}, {"id": "anat-niere-02", "ch": "7 Niere, Retroperitoneum, Becken", "q": "Wohin mündet die Vena suprarenalis sinistra?", "o": ["Direkt in die Vena cava inferior", "In die Vena lumbalis ascendens", "In die Vena phrenica inferior", "In die Vena renalis sinistra"], "a": 3, "e": "Rechts mündet die V. suprarenalis dextra direkt in die V. cava inferior; ebenso die V. testicularis/ovarica: links in die V. renalis, rechts in die V. cava."}, {"id": "anat-niere-03", "ch": "7 Niere, Retroperitoneum, Becken", "q": "Welche Kombination aus Nierengefäßen ist richtig?", "o": ["Rechte Arteria renalis und linke Vena renalis sind länger", "Rechte Arteria renalis und rechte Vena renalis sind länger", "Linke Arteria renalis und rechte Vena renalis sind länger", "Linke Arteria renalis und linke Vena renalis sind länger"], "a": 0, "e": "Die Aorta liegt links, die V. cava inferior rechts der Mittellinie: Die rechte A. renalis zieht hinter der V. cava, die linke V. renalis vor der Aorta."}, {"id": "anat-niere-04", "ch": "7 Niere, Retroperitoneum, Becken", "q": "Aus welchen Gefäßen stammen die Arteriae suprarenales superior, media und inferior?", "o": ["Truncus coeliacus, Aorta abdominalis, A. renalis", "A. phrenica inferior, Aorta abdominalis, A. renalis", "Aorta abdominalis, A. renalis, A. phrenica inferior", "A. renalis, A. phrenica inferior, Aorta abdominalis"], "a": 1, "e": "Die Nebenniere wird dreifach arteriell, aber meist von nur einer Vene drainiert; Cortisol entsteht in der Zona fasciculata der Nebennierenrinde."}, {"id": "anat-niere-05", "ch": "7 Niere, Retroperitoneum, Becken", "q": "Welches Gefäß versorgt das obere Drittel des Ureters arteriell?", "o": ["Arteria obturatoria", "Arteria uterina", "Arteria lumbalis", "Arteria renalis"], "a": 3, "e": "Der Ureter erhält segmentale Äste: oben aus A. renalis, mittig aus Aorta/A. testicularis bzw. ovarica/A. iliaca communis, unten aus A. vesicalis inferior bzw. A. uterina."}, {"id": "anat-niere-06", "ch": "7 Niere, Retroperitoneum, Becken", "q": "Wie verläuft der Ureter zur Arteria uterina, und warum ist das klinisch wichtig?", "o": ["Er unterkreuzt die Arterie; Verletzungsgefahr bei Hysterektomie", "Er verläuft parallel zur Arterie; Gefahr bei Sectio caesarea", "Er überkreuzt die Arterie; Verletzungsgefahr bei Appendektomie", "Er unterkreuzt die Arterie; Gefahr bei Leistenhernien-OP"], "a": 0, "e": "Merkspruch 'water under the bridge': Ca. 2 cm lateral der Cervix uteri zieht der Ureter im Parametrium (Basis des Lig. latum) unter der A. uterina hindurch."}, {"id": "anat-niere-07", "ch": "7 Niere, Retroperitoneum, Becken", "q": "Wie liegt der Ureter zum Nervus genitofemoralis auf dem Musculus psoas?", "o": ["Der Nerv überkreuzt den Ureter ventral", "Der Ureter überkreuzt den Nerv ventral", "Der Ureter liegt dorsal des Musculus psoas", "Beide verlaufen getrennt in eigener Faszie"], "a": 1, "e": "Der Ureter zieht auf dem M. psoas major nach kaudal und liegt dabei ventral des N. genitofemoralis (der Nerv unterkreuzt ihn)."}, {"id": "anat-niere-08", "ch": "7 Niere, Retroperitoneum, Becken", "q": "Wo liegen die drei physiologischen Ureterengen?", "o": ["Nierenhilum, Kreuzung Arteria renalis, Blasenhals", "Nierenkelche, Kreuzung Vasa ovarica, Trigonum", "Nierenbecken, Kreuzung Arteria uterina, Urethra", "Nierenbeckenabgang, Kreuzung Vasa iliaca, Blasenwand"], "a": 3, "e": "An den Engen bleiben Harnsteine bevorzugt hängen (engste Stelle meist der intramurale Abschnitt) – Koliken mit Ausstrahlung in die Leiste."}, {"id": "anat-niere-09", "ch": "7 Niere, Retroperitoneum, Becken", "q": "Auf welcher Wirbelhöhe projiziert sich etwa der untere Pol der linken Niere?", "o": ["Etwa auf Höhe des 12. Brustwirbels", "Etwa auf Höhe des 3. Lendenwirbels", "Etwa auf Höhe des 5. Lendenwirbels", "Etwa auf Höhe des 1. Lendenwirbels"], "a": 1, "e": "Linke Niere ca. Th11/12 bis L2/3 (Hilum ca. L1/L2); die rechte liegt wegen der Leber etwa eine halbe Wirbelhöhe tiefer."}, {"id": "anat-niere-10", "ch": "7 Niere, Retroperitoneum, Becken", "q": "Welche Nerven liegen dorsal der Niere und erklären fortgeleitete Schmerzen bei Nierenerkrankungen?", "o": ["Nervus phrenicus, vagus, splanchnicus major", "Nervus femoralis, obturatorius, ischiadicus", "Nervus subcostalis, iliohypogastricus, ilioinguinalis", "Nervus pudendus, genitofemoralis, cutaneus femoris"], "a": 2, "e": "Diese Nerven ziehen auf dem M. quadratus lumborum hinter der Niere; Reizung führt zu Schmerzen in Flanke, Leiste und Genitalregion."}, {"id": "anat-niere-11", "ch": "7 Niere, Retroperitoneum, Becken", "q": "Welche Nierenkapsel ist bei Dehnung (z. B. Harnstau) schmerzempfindlich?", "o": ["Fascia renalis", "Capsula fibrosa", "Tunica muscularis", "Capsula adiposa"], "a": 1, "e": "Die straffe Capsula fibrosa liegt dem Parenchym direkt an; die Capsula adiposa (Fettkapsel) und Fascia renalis (Gerota) umhüllen sie außen."}, {"id": "anat-niere-12", "ch": "7 Niere, Retroperitoneum, Becken", "q": "Welche Arterie anastomosiert mit der Arteria uterina, und in welchem Band verläuft sie zum Ovar?", "o": ["Arteria iliaca interna; Ligamentum latum", "Arteria ovarica; Ligamentum suspensorium ovarii", "Arteria vaginalis; Ligamentum teres uteri", "Arteria ovarica; Ligamentum ovarii proprium"], "a": 1, "e": "Die A. ovarica entspringt aus der Aorta abdominalis; bei einer Ovartorsion wird die Gefäßversorgung abgeklemmt."}, {"id": "anat-niere-13", "ch": "7 Niere, Retroperitoneum, Becken", "q": "Welcher Raum ist bei der stehenden Frau der tiefste Punkt der Peritonealhöhle?", "o": ["Recessus hepatorenalis", "Fossa ischioanalis", "Excavatio rectouterina", "Excavatio vesicouterina"], "a": 2, "e": "Douglas-Raum: Hier sammeln sich Flüssigkeit, Blut oder Eiter; beim Mann entspricht ihm die Excavatio rectovesicalis."}, {"id": "anat-niere-14", "ch": "7 Niere, Retroperitoneum, Becken", "q": "Welche Drüse bildet den größten Anteil des Ejakulats?", "o": ["Prostata (Vorsteherdrüse)", "Glandulae vesiculosae", "Glandulae bulbourethrales", "Epididymis (Nebenhoden)"], "a": 1, "e": "Die paarigen Bläschendrüsen liefern ca. 60–70 % (fruktosereiches Sekret), die unpaare Prostata ca. 30 %; in der Epididymis reifen und lagern die Spermien."}], "sum": "# Anatomie Thorax/Abdomen – Lernzusammenfassung zu den Altfragen (D&A Stofferin)\n\nGrundlage: studentische Altfragen (Stecken + mündliche Fragen, Assessment 1–4). Ergänzt um gesichertes Lehrbuchwissen; Fehler im Altfragen-Dokument sind am Ende gesammelt (Abschnitt „Korrekturen“). Stoff aus Kopf/Hals und Extremitäten (Teile von Assessment 3/4) ist hier nicht enthalten.\n\n---\n\n## 1 Herz und große Gefäße\n\n### Koronararterien\n\n| Gefäß | Ursprung / Verlauf | Versorgungsgebiet (Normalversorgungstyp) |\n|---|---|---|\n| A. coronaria sinistra (LCA) | Sinus aortae sinister, kurzer Hauptstamm hinter dem Truncus pulmonalis | teilt sich in RIVA und R. circumflexus |\n| R. interventricularis anterior (RIVA, LAD) | Sulcus interventricularis anterior bis zur Herzspitze | Vorderwand linker Ventrikel, vordere 2/3 des Septums (Rr. interventriculares septales), Teil der Vorderwand rechts |\n| R. circumflexus (RCX) | linker Sulcus coronarius nach dorsal | linker Vorhof, Seiten- und Hinterwand linker Ventrikel (R. marginalis sinister) |\n| A. coronaria dextra (RCA) | Sinus aortae dexter, rechter Sulcus coronarius | rechter Vorhof, rechter Ventrikel, Hinterwand-Anteile, hinteres 1/3 des Septums; meist Sinus- und AV-Knoten |\n| R. interventricularis posterior (RIVP) | Sulcus interventricularis posterior | Hinterwand, hinteres Septumdrittel |\n\n- Koronarostien: direkt oberhalb der Aortenklappe in den Sinus aortae → **erste Abgänge der Aorta**.\n- Durchblutung v. a. in der **Diastole** (systolische Kompression der intramuralen Gefäße).\n- **Vorderwandinfarkt** = Verschluss des RIVA.\n\n### Versorgungstypen\n\n| Typ | Häufigkeit (ca.) | RIVP stammt aus | Besonderheit |\n|---|---|---|---|\n| Normal-/ausgeglichener Typ | 70 % | A. coronaria dextra | RCA versorgt rechten Ventrikel + hinteres Septum |\n| Rechtsversorgungstyp | 10–15 % | A. coronaria dextra | RCA versorgt zusätzlich Teile der linken Hinterwand |\n| Linksversorgungstyp | 10–15 % | R. circumflexus | LCA versorgt gesamtes Septum; AV-Knotenarterie aus RCX |\n\n### Erregungsbildungs- und -leitungssystem (EBLS)\n\n| Struktur | Lage | Gefäß |\n|---|---|---|\n| Sinusknoten (primärer Schrittmacher, 60–80/min) | subepikardial im Sulcus terminalis an der Mündung der V. cava superior | R. nodi sinuatrialis, ca. 60 % aus RCA, ca. 40 % aus LCA/RCX |\n| AV-Knoten (sekundärer Schrittmacher, 40–60/min; Verzögerung) | im **Koch-Dreieck** des rechten Vorhofs | R. nodi atrioventricularis, ca. 80–90 % aus RCA (Crux cordis) |\n| His-Bündel | durchbohrt das Trigonum fibrosum dextrum, Pars membranacea septi | AV-Knotenarterie + Septaläste des RIVA |\n| Tawara-Schenkel | rechts über die Trabecula septomarginalis zum M. papillaris anterior | Septaläste (RIVA/RIVP) |\n\n- **Koch-Dreieck**: Todaro-Sehne (Valvula v. cavae inf. → Zentralkörper), Ansatzlinie der Cuspis septalis der Trikuspidalklappe, Ostium sinus coronarii. Inhalt: AV-Knoten.\n- „EBLS-Gefäß“ in Altfragen = A. coronaria dextra (Achtung Linksversorgungstyp).\n- **Herzskelett** (Anuli fibrosi, Trigona fibrosa) isoliert Vorhof- und Kammermyokard elektrisch → Erregung nur über AV-Knoten → zeitliche Abfolge Vorhof- vor Kammerkontraktion (Füllung, dann Auswurf); zugleich Ventilebene/Klappenansatz.\n\n### Herzhöhlen und Klappen\n\n- **Rechter Vorhof**: Sinus venarum cavarum (glatt) vs. Atrium proprium mit Mm. pectinati; Grenze innen Crista terminalis, außen Sulcus terminalis. Ostien: V. cava sup./inf., Sinus coronarius (mit Valvula sinus coronarii), Valvula venae cavae inferioris (Eustachi; fetal Leitung zum Foramen ovale).\n- **Fossa ovalis** im Septum interatriale (rechts) mit Limbus = Rest des Foramen ovale; **PFO** → paradoxe Embolie.\n- **Rechter Ventrikel**: Einstrombahn (Trikuspidalklappe, Trabeculae carneae) und Ausstrombahn (**Conus arteriosus**, glatt → Pulmonalklappe), getrennt durch **Crista supraventricularis** (+ Trabecula septomarginalis).\n- **Linker Ventrikel**: Ausstrombahn = Vestibulum aortae → Aortenklappe; vorderes Mitralsegel trennt Ein- und Ausstrom.\n- **Septum interventriculare**: Pars muscularis + Pars membranacea (VSD-Prädilektion); außen markiert durch Sulci interventriculares anterior/posterior.\n\n| Klappe | Typ | Segel/Taschen |\n|---|---|---|\n| Valva tricuspidalis | Segelklappe | Cuspis anterior, posterior, **septalis** |\n| Valva mitralis (bicuspidalis) | Segelklappe | Cuspis anterior, posterior |\n| Valva aortae | Taschenklappe | Valvula semilunaris dextra, sinistra, posterior |\n| Valva trunci pulmonalis | Taschenklappe | Valvula semilunaris anterior, dextra, sinistra |\n\n- Taschenklappen: **Nodulus** (Knötchen mittig am freien Rand), seitlich Lunulae.\n- **Papillarmuskeln** + Chordae tendineae: verhindern das Durchschlagen der Segel in den Vorhof während der Systole (sie öffnen die Klappe nicht).\n- **Pulmonalklappe** liegt nicht in der Ventilebene (höher, ventral).\n- Herzränder: Margo dexter (acutus, rechter Ventrikel), **Margo obtusus** = linker Rand (linker Ventrikel).\n\n### Herzvenen\n\n| Vene | Verlauf | Mündung |\n|---|---|---|\n| V. cardiaca magna | Sulcus interventricularis anterior (mit RIVA), dann Sulcus coronarius links | Sinus coronarius |\n| V. cardiaca media (V. interventricularis posterior) | Sulcus interventricularis posterior (mit RIVP) | Sinus coronarius |\n| V. cardiaca parva | rechter Sulcus coronarius | Sinus coronarius |\n| Sinus coronarius | hinterer Sulcus coronarius | rechter Vorhof zwischen Ostium v. cavae inf. und Trikuspidalklappe |\n\n### Venenkreuz und große Gefäße\n\n- **Venenkreuz** (Herzhinterseite): horizontale Achse Vv. pulmonales (O2-reich, 2 je Seite → linker Vorhof) kreuzt vertikale Achse V. cava superior/inferior.\n- **Arcus aortae**, Abgänge: Truncus brachiocephalicus → A. carotis communis sinistra → A. subclavia sinistra.\n- **Lig. arteriosum**: obliterierter Ductus arteriosus (Botalli) zwischen Truncus pulmonalis/A. pulmonalis sinistra und Aortenbogen; N. laryngeus recurrens sinister schlingt sich lateral davon um den Bogen.\n- Fetale Reste: Fossa ovalis (Foramen ovale), Lig. arteriosum (Ductus arteriosus), Lig. venosum (Ductus venosus), Lig. teres hepatis (V. umbilicalis), Plicae umbilicales mediales (Aa. umbilicales), Plica umbilicalis mediana (Urachus).\n- Vv. brachiocephalicae: entstehen im Venenwinkel aus V. jugularis interna + V. subclavia; **links länger** (zieht vor dem Aortenbogen nach rechts).\n\n---\n\n## 2 Lunge, Trachea, Bronchien, Mediastinum\n\n### Trachea und Bronchien\n\n- Trachea: hufeisenförmige Cartilagines tracheales, dorsal **Paries membranaceus** (M. trachealis) → grenzt an Ösophagus.\n- **Bifurcatio tracheae** ca. Th4 (Angulus sterni); innen **Carina tracheae**.\n- Lymphknoten an der Bifurkation: **Nll. tracheobronchiales inferiores** (Weg: intrapulmonal → bronchopulmonal/hilär → tracheobronchial → paratracheal → Truncus bronchomediastinalis).\n\n| Merkmal | Bronchus principalis dexter | Bronchus principalis sinister |\n|---|---|---|\n| Länge | kurz (ca. 1–2,5 cm) | länger (ca. 4–5 cm) |\n| Weite | weiter | enger |\n| Winkel | **steiler** (ca. 20–25°) | flacher (ca. 45°, Aortenbogen) |\n| Fremdkörperaspiration | **häufiger** | seltener |\n| Lage zur A. pulmonalis | Oberlappenbronchus **eparteriell** | Hauptbronchus **hyparteriell** |\n\n### Lungenhilum\n\n| | Rechts | Links |\n|---|---|---|\n| kranial | eparterieller Oberlappenbronchus | A. pulmonalis sinistra |\n| mittig | A. pulmonalis dextra (kaudal vom Oberlappenbronchus) | Bronchus principalis sinister |\n| ventral-kaudal | Vv. pulmonales | Vv. pulmonales |\n| unterhalb | Lig. pulmonale (Pleuraduplikatur) | Lig. pulmonale |\n\n### Lappen und Segmente\n\n| | Rechte Lunge | Linke Lunge |\n|---|---|---|\n| Lappen | Ober-, Mittel-, Unterlappen | Ober- (mit Lingula), Unterlappen |\n| Fissuren | Fissura obliqua + horizontalis | nur Fissura obliqua |\n| Segmente | 10 (S1–S10) | 9 (S7 fehlt; S1+S2 oft apikoposterior) |\n| Besonderheiten | Mittellappen (S4, S5) | **Lingula** (S4, S5) = Äquivalent des Mittellappens; **Incisura cardiaca** am Vorderrand des Oberlappens |\n\n- Lungenflächen: Facies costalis, mediastinalis (mit Pars vertebralis), diaphragmatica (= Basis pulmonis), Facies interlobares; Apex pulmonis.\n- **Segmentgefäße**: Äste der A. pulmonalis (und Rr. bronchiales) verlaufen **intrasegmental** mit dem Segmentbronchus; Vv. pulmonales **intersegmental** (Segmentgrenzen).\n- **Apex pulmonis**: kranial davon A./V. subclavia und Plexus brachialis, Ganglion stellatum → **Pancoast-Tumor** (Plexusschäden, Horner-Syndrom).\n\n### Mediastinum und Nerven\n\n- Rechts neben der Trachea (Mediastinum superius): **Arcus venae azygos** (über rechten Hauptbronchus zur V. cava superior), V. cava superior, N. vagus dexter; lateral Pleura/rechter Oberlappen.\n- **N. vagus**: Rr. bronchiales → Bronchokonstriktion, Sekretion; bildet am Ösophagus den Plexus oesophageus → Truncus vagalis anterior (überwiegend links) und posterior (überwiegend rechts).\n- **N. laryngeus recurrens**: links um den Arcus aortae (lateral des Lig. arteriosum), rechts um die A. subclavia dextra; gibt Rr. tracheales und oesophageales; Läsion → Heiserkeit.\n- **N. phrenicus** (C3–C5): motorisch Zwerchfell; sensibel Perikard, Pleura mediastinalis, zentrale Pleura diaphragmatica, Peritoneum unter dem Zwerchfell/Leberkapsel; verläuft mit den Vasa pericardiacophrenica (aus A. thoracica interna).\n- Pleura costalis: Nn. intercostales; Pleura visceralis: schmerzunempfindlich.\n\n---\n\n## 3 Ösophagus, Magen, Duodenum\n\n### Ösophagus\n\n| Abschnitt | Arterien | Venen |\n|---|---|---|\n| Pars cervicalis | A. thyroidea inferior | V. thyroidea inferior |\n| Pars thoracica | Rr. oesophageales der Aorta thoracica, Rr. bronchiales | V. azygos / hemiazygos |\n| Pars abdominalis | A. gastrica sinistra, A. phrenica inferior | V. gastrica sinistra → V. portae (**portokavale Anastomose**, Ösophagusvarizen) |\n\n- **Engen**: obere (Ringknorpel, C6), mittlere (Aortenbogen/linker Hauptbronchus, ca. Th4), untere (Hiatus oesophageus, Th10).\n- Entfernung vordere Zahnreihe → Kardia ca. **40 cm** (Gastroskopie; Ösophagusbeginn ca. 15 cm).\n- **Funktioneller Verschluss** (unterer Ösophagussphinkter): spiralige Wandmuskulatur (Wringmechanismus), Zwerchfellschenkel, spitzer **His-Winkel**, submuköses Venenpolster, **Lig. phrenicooesophageale (Laimer-Membran)**, Druckgradient Thorax/Abdomen. Insuffizienz → Reflux, Refluxösophagitis, Barrett-Ösophagus.\n- Oberer Ösophagussphinkter: muskulär (M. cricopharyngeus, Killian).\n\n### Magen\n\n- Abschnitte: Pars cardiaca – Fundus (Magenblase im Röntgen im Stehen) – Corpus – Pars pylorica (Antrum pyloricum, **Canalis pyloricus**, Pylorus).\n- **Incisura cardialis** (His-Winkel), **Incisura angularis** (trennt Corpus und Pars pylorica funktionell).\n- Curvatura minor (Omentum minus), Curvatura major (Omentum majus, Lig. gastrocolicum).\n- Muskelschichten von außen: Stratum longitudinale (verstärkt an den Kurvaturen) → Stratum circulare (M. sphincter pyloricus) → Fibrae obliquae.\n- **Magenstraße**: längs gerichtete Plicae gastricae an der Curvatura minor.\n- Innervation: parasympathisch N. vagus (Trunci vagales), sympathisch N. splanchnicus major.\n- Magenkarzinom: hämatogen über V. portae → Leber; lymphogen über Nll. gastrici entlang der Kurvaturen.\n\n| Region | Arterie | Ursprung |\n|---|---|---|\n| Curvatura minor | A. gastrica sinistra | Truncus coeliacus |\n| | A. gastrica dextra | A. hepatica propria (oder communis) |\n| Curvatura major | A. gastroomentalis dextra | A. gastroduodenalis |\n| | A. gastroomentalis sinistra | A. splenica |\n| Fundus / Kardia | Aa. gastricae breves, A. gastrica posterior | A. splenica |\n| | Rr. oesophageales | A. gastrica sinistra |\n\n### Duodenum\n\n| Abschnitt | Peritoneum | Merkmale |\n|---|---|---|\n| Pars superior (Bulbus/Ampulle) | **intraperitoneal** | Ulcus duodeni; dahinter A. gastroduodenalis, Ductus choledochus |\n| Pars descendens | sekundär retroperitoneal | Plica longitudinalis (Ductus choledochus) → Papilla duodeni major (Vater; Ductus choledochus + Ductus pancreaticus), Papilla minor |\n| Pars horizontalis (inferior) | sekundär retroperitoneal | zwischen Aorta und A. mesenterica superior → **A.-mesenterica-superior-Syndrom (Wilkie)** |\n| Pars ascendens | sekundär retroperitoneal | → Flexura duodenojejunalis am **M. suspensorius duodeni (Treitz)** |\n\n- Plicae circulares (Kerckring) ab Pars descendens, am dichtesten distales Duodenum/proximales Jejunum.\n\n---\n\n## 4 Dünn- und Dickdarm\n\n### Dünndarm\n\n| | Jejunum | Ileum |\n|---|---|---|\n| Kerckring-Falten | hoch, dicht | niedriger, distal fehlend |\n| Gefäßarkaden | wenige, lange Vasa recta | mehrere Reihen, kurze Vasa recta |\n| Lymphatisches Gewebe | Einzelfollikel | **Peyer-Plaques** (distal, antimesenterial) |\n| Besonderheit | – | **Meckel-Divertikel** (Rest des Ductus omphaloentericus, ca. 60–100 cm vor der Bauhin-Klappe) |\n\n- Ostium ileale auf der **Papilla ilealis** mit Labrum ileocolicum und Labrum ileocaecale (Bauhin-Klappe), Frenula.\n\n### Dickdarm\n\n- Kennzeichen: **Taeniae coli** (Stratum longitudinale), **Haustra coli** mit **Plicae semilunares** (Stratum circulare), **Appendices epiploicae**.\n\n| Taenie | Lage am Colon transversum | Namensgeber |\n|---|---|---|\n| Taenia mesocolica | dorsal | Ansatz Mesocolon transversum |\n| Taenia omentalis | ventral-kranial | Ansatz Omentum majus |\n| Taenia libera | frei, ventral-kaudal | – (Wegweiser zur Appendix; alle Taenien treffen sich an der Appendixbasis) |\n\n| Kolonabschnitt | Peritoneum | Arterie |\n|---|---|---|\n| Caecum / Appendix | intraperitoneal | A. ileocolica (A. appendicularis) |\n| Colon ascendens | sekundär retroperitoneal | A. colica dextra (AMS) |\n| Flexura coli dextra | – | unter der Leber, tiefer als die linke |\n| Colon transversum | intraperitoneal (Mesocolon transversum) | A. colica media (AMS) |\n| Flexura coli sinistra | – | höher, Lig. phrenicocolicum; Kontakt Facies colica der Milz |\n| Colon descendens | sekundär retroperitoneal | A. colica sinistra (AMI) |\n| Colon sigmoideum | intraperitoneal (Mesocolon sigmoideum) | Aa. sigmoideae (AMI) |\n| Rectum (oben) | | A. rectalis superior (AMI) |\n\n- Riolan-Anastomose: A. colica media ↔ A. colica sinistra; Grenze AMS/AMI ≈ Cannon-Böhm-Punkt (linkes Drittel Colon transversum).\n- **A. mesenterica superior** (L1): A. pancreaticoduodenalis inferior, Aa. jejunales/ileales, A. ileocolica, A. colica dextra, A. colica media.\n- **A. mesenterica inferior** (L3): A. colica sinistra, Aa. sigmoideae, A. rectalis superior.\n- Venen: V. mesenterica inferior → meist V. splenica; V. splenica + V. mesenterica superior → V. portae (hinter Pankreashals).\n- **V. rectalis superior** → V. mesenterica inferior → V. portae; Vv. rectales media/inferior → V. iliaca interna → V. cava inferior ⇒ **portokavale Anastomose** im Rektum (portale Hypertension; Metastasierung Leber vs. Lunge).\n- **Psoaszeichen**: retrozäkale Appendizitis reizt Peritoneum über dem M. iliopsoas; über diesen Muskel können sich retroperitoneale Entzündungen zum Oberschenkel ausbreiten.\n\n---\n\n## 5 Leber, Galle, Pankreas, Milz\n\n### Leber – Lappen, Bänder, Flächen\n\n| Struktur | Inhalt / Bedeutung |\n|---|---|\n| Lig. falciforme hepatis | Peritonealfalte zur vorderen Bauchwand; trennt anatomischen rechten/linken Lappen |\n| Lig. teres hepatis | obliterierte **V. umbilicalis**, im freien Rand des Lig. falciforme |\n| Lig. venosum | obliterierter **Ductus venosus (Arantii)**, Fissura lig. venosi |\n| Lig. coronarium | begrenzt die **Area nuda** (peritonealfrei, am Zwerchfell), läuft in Ligg. triangularia aus |\n| Appendix fibrosa hepatis | Spitze des linken Lappens (Ende des Lig. triangulare sinistrum) |\n| Lobus quadratus | zwischen Gallenblase und Lig. teres; funktionell links (Segment IV) |\n| Lobus caudatus | zwischen V. cava inf. und Lig. venosum; Verbindung zum rechten Lappen: Processus caudatus (+ Lig. venae cavae); Segment I, beidseits versorgt |\n\n- **Funktionelle Teilung**: Cantlie-Linie V. cava inferior – Fundus vesicae biliaris (V. hepatica media).\n  - funktionell rechts: Lobus dexter + rechter Teil des Lobus caudatus → Ductus hepaticus dexter\n  - funktionell links: Lobus sinister + Lobus quadratus + linker Teil des Lobus caudatus → Ductus hepaticus sinister\n- **Porta hepatis**: V. portae (größtes Gefäß, dorsal), A. hepatica propria, Ductus hepaticus.\n- **V. portae** ≈ 75 % des Leberblutes = *Vas publicum*; A. hepatica propria ≈ 25 % = *Vas privatum*.\n- Vv. hepaticae (dextra, media, sinistra) → V. cava inferior direkt unter dem Zwerchfell.\n\n### Truncus coeliacus (Höhe Th12/L1)\n\n| Ast | Weitere Äste |\n|---|---|\n| A. gastrica sinistra | Rr. oesophageales; Curvatura minor |\n| A. hepatica communis | → A. gastroduodenalis (A. gastroomentalis dextra, Aa. pancreaticoduodenales superiores anterior/posterior, A. supraduodenalis) und → A. hepatica propria (A. gastrica dextra; R. dexter mit **A. cystica**; R. sinister) |\n| A. splenica (lienalis) | Rr. pancreatici, A. pancreatica dorsalis/magna/caudae, Aa. gastricae breves, A. gastrica posterior, A. gastroomentalis sinistra, Rr. splenici |\n\n- Pankreaskopf: Arkaden aus Aa. pancreaticoduodenales superiores (A. gastroduodenalis) und inferiores (A. mesenterica superior) → Kollaterale Truncus coeliacus ↔ AMS.\n\n### Gallenwege\n\n- Gallenblase: Fundus (überragt Leberrand; MCL/9. Rippenknorpel) – Corpus – Collum → Ductus cysticus (Plica spiralis).\n- Ductus hepaticus dexter + sinister → Ductus hepaticus communis; + Ductus cysticus → **Ductus choledochus** (Lig. hepatoduodenale → hinter Pars superior duodeni → Pankreaskopf → Papilla duodeni major).\n- **Calot-Dreieck**: Ductus cysticus, Ductus hepaticus communis, Leberunterfläche; Inhalt **A. cystica** (meist aus R. dexter der A. hepatica propria). Varianten (z. B. doppelte A. cystica) → Blutungsgefahr bei Cholezystektomie.\n\n### Pankreas und Milz\n\n- Pankreas: Caput (mit Processus uncinatus, umgeben vom Duodenum), Collum, Corpus, Cauda. Sekundär retroperitoneal außer **Cauda** (intraperitoneal im Lig. splenorenale, reicht bis zum Milzhilum).\n- Milz: intraperitoneal; Facies diaphragmatica, gastrica, renalis, **colica** (Flexura coli sinistra); Hilum mit Cauda pancreatis.\n- **A. splenica**: geschlängelt am Pankreasoberrand, teilt sich in Segmentarterien (funktionelle Endarterien → Milzinfarkte).\n\n---\n\n## 6 Zwerchfell, Bauchwand, Peritoneum, Leitungsbahnen\n\n### Zwerchfell\n\n- Pars sternalis, Pars costalis, Pars lumbalis (Crus dextrum/sinistrum) → Centrum tendineum.\n- Schwachstellen: **Trigonum sternocostale** (Larrey; Vasa epigastrica superiora), Trigonum lumbocostale (Bochdalek).\n\n| Öffnung | Höhe | Inhalt |\n|---|---|---|\n| Foramen venae cavae (Centrum tendineum) | Th8 | V. cava inferior, R. phrenicoabdominalis des N. phrenicus dexter |\n| Hiatus oesophageus (Pars lumbalis) | Th10 | Ösophagus, Trunci vagales |\n| Hiatus aorticus (hinter **Lig. arcuatum medianum**) | Th12 | Aorta, Ductus thoracicus |\n\n- Innervation: N. phrenicus (C3–C5); Gefäße: Vasa pericardiacophrenica (A. thoracica interna), A. phrenica inferior (Aorta abdominalis).\n- Lig. phrenicooesophageale fixiert Ösophagus im Hiatus.\n\n### Vordere Bauchwand (Innenansicht)\n\n| Falte | Inhalt | Grube lateral davon |\n|---|---|---|\n| Plica umbilicalis mediana | Urachus | Fossa supravesicalis |\n| Plica umbilicalis medialis | obliterierte A. umbilicalis | Fossa inguinalis medialis (direkte Hernie) |\n| Plica umbilicalis lateralis | Vasa epigastrica inferiora (aus A. iliaca externa) | **Fossa inguinalis lateralis** = innerer Leistenring (indirekte Hernie) |\n\n- A. thoracica interna → A. epigastrica superior ↔ A. epigastrica inferior (Rektusscheide). V. thoracica interna → V. brachiocephalica.\n\n### Peritonealverhältnisse\n\n| Lage | Organe |\n|---|---|\n| intraperitoneal | Magen, Pars superior duodeni, Jejunum, Ileum, Caecum/Appendix, Colon transversum, Colon sigmoideum, Leber (außer Area nuda), Gallenblase, Milz, Cauda pancreatis |\n| sekundär retroperitoneal | Duodenum (Pars descendens, horizontalis, ascendens), Pankreas (Caput–Corpus), Colon ascendens, Colon descendens |\n| primär retroperitoneal | Nieren, Nebennieren, Ureteren, Aorta, V. cava inferior, Truncus sympathicus |\n\n### Aorta abdominalis\n\n- Viszeral unpaar: Truncus coeliacus, A. mesenterica superior, A. mesenterica inferior.\n- Viszeral paarig: Aa. suprarenales mediae, Aa. renales, Aa. testiculares/ovaricae.\n- **Parietal**: Aa. phrenicae inferiores, Aa. lumbales, A. sacralis mediana.\n- Bifurkation L4 → Aa. iliacae communes.\n\n---\n\n## 7 Niere, Retroperitoneum, Becken (Assessment 2/3, Auswahl)\n\n- Lage: linke Niere ca. Th11/12–L2/3 (Hilum L1/L2, unterer Pol ca. L3); rechte etwas tiefer.\n- Hüllen: Capsula fibrosa (schmerzempfindlich bei Dehnung) – Capsula adiposa – Fascia renalis (Gerota). Parenchym: Cortex, Medulla (Pyramiden mit Papillae), Columnae renales zwischen den Pyramiden; Calices minores → majores → Pelvis.\n- Hinter der Niere: N. subcostalis, N. iliohypogastricus, N. ilioinguinalis (fortgeleitete Schmerzen).\n\n| | Rechts | Links |\n|---|---|---|\n| A. renalis | **länger** (hinter V. cava) | kürzer |\n| V. renalis | kürzer | **länger**, vor der Aorta unter der AMS (**Nussknacker-Syndrom**) |\n| V. suprarenalis | V. cava inferior | V. renalis sinistra |\n| V. testicularis/ovarica | V. cava inferior | V. renalis sinistra (rechtwinklig → Varikozele links häufiger) |\n\n- Nebenniere: A. suprarenalis superior (A. phrenica inferior), media (Aorta abdominalis), inferior (A. renalis); Cortisol aus der Zona fasciculata der Rinde.\n- **Ureter**: Engen am Nierenbeckenabgang, an der Kreuzung der Vasa iliaca, beim Durchtritt durch die Blasenwand. Liegt auf dem M. psoas **ventral** des N. genitofemoralis. Versorgung oben A. renalis, mittig Aorta/A. testicularis-ovarica/A. iliaca communis, unten A. vesicalis inferior bzw. A. uterina. Im Parametrium **unterkreuzt** er die A. uterina („water under the bridge“) → Gefahr bei Hysterektomie.\n- A. ovarica (aus Aorta) im Lig. suspensorium ovarii, anastomosiert mit der A. uterina; Ovartorsion → Ischämie. Lig. ovarii proprium: Ovar–Tubenwinkel.\n- Excavatio rectouterina (**Douglas-Raum**) = tiefster Punkt der Peritonealhöhle der Frau; beim Mann Excavatio rectovesicalis.\n- Ejakulat: Glandulae vesiculosae (größter Anteil, paarig), Prostata (unpaar); Spermienreifung/-speicherung in der Epididymis.\n\n---\n\n## Korrekturen zum Altfragen-Dokument\n\n| Stelle im Dokument | Problem | Richtig |\n|---|---|---|\n| „Ursprungsarterie der A. gastrica sinistra → A. hepatica propria“ | falsch | Truncus coeliacus |\n| „Rr. tracheales … Pars thoracica des Oesophagus segmental (A. thoracica interna)“ | falsch | segmental: Rr. oesophageales der Aorta thoracica |\n| „Lig., welches Aorta vor dem Einfallen schützt (Lig. arteriosum)“ | falsche Funktion | Rest des Ductus arteriosus |\n| Stratum circulare → „Taenien“ | widersprüchlich | Taenien = Stratum longitudinale; Plicae semilunares/Haustren = Stratum circulare |\n| Intrasegmentale Gefäße: „Aa. und Vv. pulmonales“ | falsch für Venen | Aa. pulmonales intrasegmental, Vv. pulmonales intersegmental |\n| Oberes Mesenterialsyndrom = „Mesenterialarterienstenose“, „Pars ascendens“ | Verwechslung | Kompression der Pars horizontalis duodeni zwischen Aorta und AMS |\n| Koch-Dreieck: „Septum atrioventriculare“, Todaro-Sehne „zur Trikuspidalklappe“ | ungenau | Ansatz der Cuspis septalis; Todaro-Sehne zum Zentralkörper |\n| „Septum supraventricularis“ | Begriff | Crista supraventricularis |\n| Doppelte A. cystica „20 %“ vs. „15 %“ | widersprüchlich | Variante, Häufigkeit je nach Quelle ca. 15–25 % |\n| „Welche Arterie wird vom Ureter überkreuzt? A. uterina“ | Richtung falsch | A. uterina überkreuzt den Ureter |\n| „Struktur, die im Lig. latum die Vasa ovarica überkreuzt (Ureter)“ | Gefäß falsch | im Parametrium kreuzt die A. uterina; Vasa ovarica im Lig. suspensorium ovarii |\n| „Welcher Nerv überkreuzt den Ureter (N. genitofemoralis)“ vs. „… unterkreuzt“ | widersprüchlich | N. genitofemoralis unterkreuzt den Ureter |\n| Papillarmuskeln „halten passiv dagegen“ | ungenau | kontrahieren aktiv in der Systole |\n| „Lippen bis Magen 30–40 cm“ vs. „Zahnreihe bis Magen ca. 40 cm“ | ungenau | Zahnreihe–Kardia ca. 40 cm |\n| Head-Zonen Niere „Th12–L3“, Ureter „T12–L2“ | abweichende Angaben | Lehrbuch meist Niere Th10–L1, Ureter Th11–L1/L2 (nicht abgefragt) |\n"}, {"id": "custom", "name": "Eigene Fragen", "q": [], "sum": ""}], "notes": {"anat-herz-09": "Dokument: septale Begrenzung als 'Ansatz des Septum atrioventriculare' und Todaro-Sehne 'zur Trikuspidalklappe' – korrekt: Ansatzlinie der Cuspis septalis; Todaro-Sehne zieht zum Zentralkörper (Trigonum fibrosum dextrum).", "anat-herz-13": "Dokument: 'Ligament, welches Aorta vor dem Einfallen schützt' – fachlich falsch; das Lig. arteriosum ist der obliterierte Ductus arteriosus.", "anat-herz-18": "Dokument schreibt 'Septum supraventricularis' – korrekt: Crista supraventricularis.", "anat-herz-21": "Dokument: 'halten passiv dagegen' – ungenau: Papillarmuskeln spannen sich aktiv mit der Kammersystole.", "anat-lunge-07": "Dokument widersprüchlich: nennt Aa. und Vv. pulmonales als intrasegmental. Korrekt: Aa. pulmonales (und Rr. bronchiales) intrasegmental, Vv. pulmonales intersegmental.", "anat-magen-02": "Dokument nennt einmal 30–40 cm 'Lippen bis Magen', einmal ca. 40 cm ab vorderer Zahnreihe – Lehrbuchwert: ca. 40 cm.", "anat-magen-04": "Dokument: 'Ursprungsgefäß der Rr. tracheales, die die Pars thoracica des Oesophagus segmental versorgt (A. thoracica interna)' – falsch; die segmentale Versorgung kommt aus der Aorta thoracica.", "anat-magen-19": "Dokument: 'Ursprungsarterie der A. gastrica sinistra -> A. hepatica propria (Truncus coeliacus)' – A. hepatica propria ist falsch; Ursprung ist der Truncus coeliacus.", "anat-magen-23": "Dokument: einmal als Mesenterialarterienstenose/Ischämie beschrieben (falsch, anderes Krankheitsbild), einmal 'Pars ascendens' – korrekt: Kompression der Pars horizontalis (inferior) duodeni.", "anat-darm-04": "Dokument widersprüchlich: schreibt dem Stratum circulare die Taenien zu und sagt im selben Satz, sie gingen aus dem Stratum longitudinale hervor. Korrekt: Taenien = Längsmuskulatur, Plicae semilunares/Haustren = Ringmuskulatur.", "anat-leber-15": "Dokument nennt einmal A. hepatica dextra, einmal A. hepatica propria – beides gemeint ist der R. dexter der A. hepatica propria. Häufigkeit doppelter A. cystica widersprüchlich angegeben (20 % vs. 15 %).", "anat-niere-06": "Dokument: 'Welche Arterie wird vom Ureter überkreuzt? → A. uterina' und 'Struktur, die im Lig. latum die Vasa ovarica überkreuzt (Ureter)' – Richtung bzw. Gefäß falsch: Die A. uterina überkreuzt den Ureter; die Vasa ovarica verlaufen im Lig. suspensorium ovarii.", "anat-niere-07": "Dokument widersprüchlich: 'Welcher Nerv überkreuzt den Ureter (N. genitofemoralis)' vs. 'Von welchem Nerv wird der Ureter unterkreuzt' – korrekt: Der N. genitofemoralis unterkreuzt den Ureter."}};